programs.sol:
"""Negative linear-path collocations, plus a document-opening signal.

Examples of the contextual response are 'passing through', 'straight line',
'long thread', and 'flow channels'. Isolated path words are weaker. Opening
tokens are usually negative, especially path/length words; their typography
and grammatical class also matter. A few Chinese path/length characters
and chat boundary markers are recognized. Other lexical variation is left out.
"""
import math

READS = ()


def nouns(text):
    words = set(text.split())
    return words | {word + 's' for word in words}


PATHS = nouns('line path pathway route road street highway track corridor '
              'lane trail channel stream pipe cable wire tunnel vein '
              'chain strand thread filament rope') | {'artery', 'arteries'}
SHAPE = set('straight linear curved horizontal vertical parallel diagonal '
            'tangent dashed dotted continuous long short length wide narrow '
            'consecutive'.split())
MOTION = set('pass passes passed passing go goes going went gone travel '
             'travels traveling travelling traveled travelled move moves '
             'moved moving run runs running ran flow flows flowed flowing '
             'navigate navigating walk walks walked walking trace traces '
             'tracing passage journey'.split())
TRANSPORT = set('transmission communication supply blood gas water rail '
                'railway electric electrical inlet outlet signaling'.split())
SEQUENCE = set('sequence series segment timeline narrative paragraph '
               'sentence episode continue continuing consecutive'.split())
DETERMINERS = set('this that these those each every some any all both'.split())
QUESTIONS = set('how what when where who why which'.split())
PERSONAL = set('i you he she it we they me him us them'.split())
POSSESSIVE = set('my your his her its our their'.split())
CONNECTORS = {'and', 'or', 'but', 'of', 'to', 'in', 'can'}
QUALIFIERS = SHAPE | MOTION | TRANSPORT | PATHS
MEASURED = SEQUENCE | {'length', 'range', 'regression'}
VEHICLES = set('car vehicle bus train truck plane ship boat flight'.split())
HEADINGS = set('title name description question answer subject topic '
               'chapter section'.split())
CJK_PATH = frozenset('线線路道街条條缆纜长長短段')


def opening(text, word):
    capital = text.strip()[:1].isupper()
    if text.isspace():
        return 0.07 if text == ' ' else 0.19
    if word.isdigit():
        return -0.065
    if word.startswith('<') and word.endswith('>'):
        return -0.03
    if word in {',', ')'}:
        return 0.14
    if word in {'line', 'lines'}:
        return -1.40
    if word in PATHS:
        return -0.80
    if (word in MOTION or word in SEQUENCE or word in VEHICLES
            or word in {'long', 'short', 'length'}):
        return -0.55
    if word in HEADINGS:
        return -0.50
    if any(c in CJK_PATH for c in word):
        return -0.70
    if word in SHAPE or word in TRANSPORT:
        return -0.40
    if word == 'the':
        return -0.22 if capital else -0.30
    if word in {'a', 'an'}:
        return -0.17
    if word in DETERMINERS:
        return -0.24
    if word in QUESTIONS:
        return -0.37 if capital else -0.24
    if word in POSSESSIVE:
        return -0.29
    if word in PERSONAL:
        return -0.085
    if word in CONNECTORS:
        if capital:
            return -0.17
        if text[:1].isspace():
            return -0.02 if word in {'of', 'but'} else 0.11
        return -0.11
    if '\ufffd' in word or any('\u4e00' <= c <= '\u9fff' for c in word):
        return -0.225
    if word.startswith(('<?', '/*', '#!', '{')):
        return -0.37
    if capital:
        return -0.25
    if word and not any(c.isalnum() for c in word):
        return -0.06
    return -0.16


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip().strip('-_').lower()
    if carry is None or carry[0] != doc:
        return (doc, 0, word), float(opening(text, word))
    _, position, previous = carry
    position += 1
    # A small opening after-effect fades with document-relative position.
    value = 0.0005 - 0.03 / math.sqrt(position)
    if word == 'through':
        value -= 0.12
        if previous in MOTION or previous in PATHS:
            value -= 0.69
    elif word in {'line', 'lines'}:
        value -= 0.04
        if previous in {'straight', 'long', 'transmission'}:
            value -= 1.06
        elif previous in QUALIFIERS:
            value -= 0.50
    elif word in PATHS:
        value -= 0.08
        if previous in QUALIFIERS:
            value -= 0.50
    elif word in MEASURED:
        if previous in SHAPE or previous in PATHS:
            value -= 0.30
    if word in {'直线', '直線'}:
        value -= 0.70
    elif word in {'线', '線', '道', '线路', '路线', '條', '条'}:
        value -= 0.15
    # Content-block and conversation boundary markers have small fixed offsets.
    if word in {'<think>', '<tool_response>'}:
        value += 0.14
    elif word == '</tool_call>':
        value -= 0.115
    elif word == '<|im_start|>':
        value -= 0.045
    elif word == '<|im_end|>':
        value += 0.035
    return (doc, position, word), float(value)

"""Negative activation for 'an' spellings, especially anal-/analy-, anim-, ann-.

This uses word families and syllable fragments, not a semantic analysis
classifier. Grammatical an/and/any are weak. Capitalization and word boundaries
strengthen some responses. Cyrillic and selected translated families are
included. Split endings and following 'of' retain an echo, reset at documents.
"""
import unicodedata

READS = ()
BOUNDARIES = ' \t\r\n._-/([{\"\''
SHORT_ROOTS = {'anal': 6.3, 'analy': 4.0, 'analys': 4.0,
               'anim': 3.0, 'anom': 2.1}
FAMILIES = (
    (('analyst',), 3.4),
    (('analys', 'analyz', 'analyti', 'analyse', 'analyze'), 2.65),
    (('analog', 'anonym'), 2.8),
    (('annotat',), 3.2),
    (('animal', 'animation'), 2.25),
    (('anime', 'animated'), 1.8),
    (('announc', 'annonce', 'ancest'), 1.5),
    (('annual', 'annivers', 'anomal', 'anx', 'anterior'), 1.1),
    (('ancient',), 0.25),
)
# Weaker grammatical onsets and inflectional fragments.
WEAK_ENDINGS = ('ance', 'ancy', 'ancer', 'ancia', 'anti', 'anni',
                'annt', 'anned', 'anner', 'angl', 'anger')
SYLLABLES = {'a': 1.65, 'e': 1.75, 'i': 1.8, 'n': 1.8, 'o': 1.4,
             'c': 1.25, 'g': 0.9, 's': 0.7, 't': 0.45,
             'j': 1.7, 'k': 0.9, 'z': 0.9, 'u': 1.7}


def lexical(token):
    bare = token.lstrip(BOUNDARIES)
    word = ''.join(c for c in unicodedata.normalize('NFD', bare.lower())
                   if not unicodedata.combining(c))
    boundary, capital = bare != token, bare[:1].isupper()
    if word.startswith('an'):
        if word == 'an':
            if token.startswith(('-', '/', '_', '.')):
                return -2.5
            return -0.95 if capital else -0.17 if boundary else -0.31
        if word.startswith(('and', 'any', 'another', 'answer')):
            return 0.0 if boundary and not capital else -0.15
        if word in SHORT_ROOTS:
            return -SHORT_ROOTS[word]
        for stems, strength in FAMILIES:
            if word.startswith(stems):
                return -(strength + 0.25 * capital)
        if word in ('ant', 'ante', 'antes', 'ants', 'ando', 'ands',
                    'anche', 'ancing', 'anza'):
            return -0.05
        if word.startswith(WEAK_ENDINGS):
            return -0.45
        if word in ('ana', 'ann', 'ans') and (
                boundary or capital and not bare.isupper()):
            return -3.6 if word == 'ana' else -2.55 if word == 'ann' else -1.7
        if word == 'ang' and not (boundary or capital):
            return -0.23
        return -SYLLABLES.get(word[2], 0.2) if len(word) <= 5 else -0.6
    if word.startswith('ан'):
        if word == 'ана' and boundary:
            return -4.3
        if word.startswith(('анализ', 'аналог')):
            return -2.6
        return -1.8 if word == 'ани' else -1.1 if len(word) == 2 else -0.6
    if word.startswith(('panel', 'canal', 'manual')):
        return -1.3
    if 'an' in word:
        return -0.06
    if '分析' in word:
        return -2.5
    if word in ('动物', '動物', '动画', '動畫', 'アニメ'):
        return -1.6
    if word in ('安', '安排', '宣布'):
        return -1.2
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = 0.0 if carry is None or carry[0] != doc else carry[1]
    native = lexical(token)
    value = native
    if token.isalpha() and not token[:1].isupper() and previous < -0.5:
        ending = token in ('s', 'es', 'ing', 'ed', 'ly', 'ies',
                           'ze', 'zing', 'ysis', 'yses', 'tical', 'ating')
        value += (0.4 if ending else 0.1) * previous
    elif token.lower() == ' of':
        value += 0.2 * previous
    return (doc, native), float(value)

"""Periods after initials and abbreviations, rather than sentence endings.

Use the previous token's spelling, length and case to estimate how
abbreviation-like it is. Familiar titles and dotted initials are strongest;
ordinary words and digits are nearly inactive. Merged punctuation weakens
this response. A separate space after a letter has a smaller positive value.
Only the previous token in the same document is read.
"""
import unicodedata

READS = ()
TITLES = set('Mr Mrs Ms Dr St Sr Jr Fr Lt'.split())
MONTHS = set('Jan Feb Mar Apr Aug Sep Sept Oct Nov Dec'.split())
REFERENCES = set('Eq eq Ref ref cf Cf pp Nos Cir Ch'.split())
OTHER_TITLES = set('Prof Rev Hon Gen Col Capt Gov Sgt'.split())
PUBLICATIONS = set('App Vet Hist Soc Vol Ed ed Res Proc Pat Dist Bd Acc '
                   'Pres Dept Rep Ann'.split())
COMPANIES = set('Inc Co Corp Ltd Bros'.split())
UNITS = set('mm cm km kg mg ft yd sec min ml mL'.split())
FUNCTION_WORDS = set('an as at be by do go he if in is it me my of on or so '
                     'to up us we and are but can for has her his how not '
                     'one our out she the too was who you'.split())
ABBREVIATIONS = (
    (1.40, TITLES), (1.02, MONTHS | REFERENCES),
    (0.86, OTHER_TITLES | COMPANIES | {'al'}),
    (0.69, PUBLICATIONS | {'No', 'NO', 'Nr'}),
    (0.75, {'fig', 'Fig', 'FIG', 'figs', 'Figs', 'FIGS', 'sub', 'sup'}),
    (1.24, {'v', 'vs', 'Vs'}), (0.94, {'p'}),
    (0.45, UNITS | {'etc', 'ibid', 'Ibid', 'ib', 'viz', 'resp', 'Resp'}),
    (0.35, {'no', 'nr'}),
)


def abbreviation_strength(previous):
    word = previous.strip()
    spaced = previous.startswith(' ')
    dotted = word.startswith('.')
    word = word[1:] if dotted else word
    if dotted and len(word) == 1 and word.isalpha():
        return 1.49 if word.isupper() else 1.21
    for strength, words in ABBREVIATIONS:
        if word in words:
            return strength
    if len(word) == 1 and word.isalpha():
        script = unicodedata.name(word, '').split(' ')[0]
        if script == 'GREEK':
            return 0.24
        if script == 'CYRILLIC':
            return 1.06 if spaced or word.isupper() else 0.11
        if word.isupper():
            return 0.98 if spaced else 0.79
        if word.islower():
            return 0.24 if not spaced and word in 'aeiouys' else (
                0.70 if spaced else 0.58)
        return 0.0
    if word in FUNCTION_WORDS:
        return 0.02
    if len(word) > 1 and set(word.upper()) <= set('IVXLC'):
        return 0.44
    if word.isalpha():
        if word.isupper():
            return 0.20 if len(word) <= 3 else 0.09
        if word.istitle():
            return {2: 0.64, 3: 0.48, 4: 0.22}.get(len(word), 0.05)
        if len(word) == 2:
            return 0.44 if spaced else 0.13
        return 0.08 if len(word) == 3 else -0.02
    return -0.02 if word.isdigit() else 0.13


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if (len(prefix.token_ids) > 1 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    if token == ' ':
        word = previous.strip()
        letter = len(word) == 1 and (word.isupper() or word.islower())
        return None, 0.34 if letter else (
            0.18 if word.isupper() and len(word) == 2 else -0.01)
    if token not in {'.', '.,', '.)', '.;', '.-', ' .'} and not (
            token.startswith('.') and token[1:].isspace()):
        return None, 0.0
    strength = abbreviation_strength(previous)
    if token == '.':
        return None, float(strength)
    if token == ' .':
        return None, 0.04 + 0.26 * max(0.0, strength)
    if token[1:].isspace():
        return None, -0.02 + 0.16 * max(0.0, strength)
    return None, 0.12 + 0.43 * max(0.0, strength)

programs.haiku:
"""Scratch v3: abbreviation periods; short unfamiliar words get a weaker response."""
import re

READS = ()

TITLES = {"mr", "mrs", "ms", "dr", "st", "jr", "sr", "prof", "rev", "hon", "sgt", "lt", "col",
          "capt", "gen", "gov", "sen", "rep", "pres", "fr"}
ABBREVS = {"co", "inc", "ltd", "corp", "dept", "univ", "dist", "supp", "inst", "assn", "vol",
           "no", "nr", "fig", "figs", "eq", "ave", "ct", "app", "cir", "vs", "v", "etc", "al",
           "cf", "vgl", "adv", "fl", "rs", "ew", "sp", "ed", "aug", "jan", "feb", "mar", "apr",
           "jun", "jul", "sept", "oct", "nov", "dec", "supt", "asst", "bd", "ibid", "approx"}
COMMON = {"a", "i", "it", "is", "me", "us", "in", "on", "up", "you", "day", "way", "own", "yet",
          "out", "not", "too", "now", "her", "one", "two", "the", "and", "to", "of", "an", "be",
          "do", "go", "so", "no", "we", "he", "she", "by", "at", "or", "as", "if", "my", "his",
          "all", "our", "was", "are", "has", "had", "may", "can", "its", "end", "ok", "yes"}

def strength(word):
    low = word.lower()
    if re.fullmatch(r"[A-Za-z]+(\.[A-Za-z]+)+", word):
        return 1.0
    if re.fullmatch(r"[A-Za-z]", word):
        return 0.9
    if low in TITLES:
        return 1.3
    if low in ABBREVS:
        return 1.0
    if re.fullmatch(r"[A-Z]{2,}|[A-Z][a-z]{2}", word):
        return 0.5
    if re.fullmatch(r"[A-Za-z]{2,3}", word) and low not in COMMON:
        return 0.4
    return 0.0

def step(carry, prefix, upstream):
    if prefix.token_strings[-1] not in (".", ".,"):
        return None, 0.0
    t = prefix.position
    lo = t - 1
    while lo > 0 and prefix.document_ids[lo - 1] == prefix.document_ids[t] and t - lo < 8:
        lo -= 1
    text = "".join(prefix.token_strings[lo:t])
    word = re.search(r"([A-Za-z.]*)$", text).group(1).strip(".")
    return None, strength(word)

programs.sol:
"""Approximate selected local word-fragment responses.

After qu, quark/quart/quotation and several Romance question-word
continuations are negative; er/ier-like continuations are positive.
Other rules cover adjoining fragments after com/con/pro/pre/mo and
re/de/fre/bre/ro/quer. Thinking delimiters have small negative biases.
Only the preceding token is remembered, and documents reset that memory.
Unlisted cases return zero: most weaker lexical responses are not explained.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ""
    left, right = previous.strip().lower(), token.lower()
    value = 0.0
    if left == "qu" and right and not right[0].isspace():
        if right in {"ark", "arks"}:
            value = -0.50
        elif right in {"art", "arts", "anta", "ante", "ais", "elle",
                       "elles", "oting", "ote", "otes", "od", "os",
                       "ads", "ang", "aint", "id"}:
            value = -0.40
        elif right in {"er", "ers", "ero", "erc", "ier", "ieran",
                       "ieren", "iser", "ert"}:
            value = 0.60
    elif left in {"com", "con", "pro", "pre", "mo"}:
        if right in {"er", "ers", "ber", "bin", "bed", "une", "unit",
                     "uni", "rade", "ien", "face", "nder", "verbs",
                     "hibition"}:
            value = 0.50
        elif right in {"versions", "version", "les"}:
            value = -0.43
    elif left in {"re", "de", "fre", "bre", "ro", "quer"}:
        if right in {"er", "iner", "ign", "igned"}:
            value = 0.40
    if token == "<think>":
        value = -0.135
    elif token == "</think>":
        value = -0.073
    return (doc, token), value

"""Detect 'with', but down-weight its predictable, fixed-phrase uses.

A new 'with' phrase gives a positive signal. 'Familiar with', 'deal with',
'contact with', and other conventional complements are weaker or negative.
Capitalized and identifier forms fire strongly. 'Of' and some translations
of 'with' give smaller signals. Unmodeled lexical responses are set to zero.
The only state is a short text tail, reset at document boundaries.
"""
import re

READS = ()


def inflections(words):
    """Regular verb endings; irregular forms are listed separately below."""
    result = set(words.split())
    for word in tuple(result):
        if word.endswith('y') and word[-2] not in 'aeiou':
            result.update((word[:-1] + 'ies', word[:-1] + 'ied'))
        else:
            result.add(word + 's')
            result.add(word + 'd' if word.endswith('e') else word + 'ed')
        result.add((word[:-1] if word.endswith('e') else word) + 'ing')
    return result


FAMILIARITY = set('familiar unfamiliar acquainted familiarity'.split())
ENGAGEMENT = inflections('engage contact interact partner cope') | set(
    'dealing dealings meeting encounter met'.split())
ASSOCIATION = inflections('''
    associate compare comply conflict coincide collide deal disagree
    struggle interfere interview collaborate confront
''') | set('''
    associated comparison concerned confused obsessed synonymous incompatible
    inconsistent filled dealt met faced playing diagnosed
'''.split())
RELATION = inflections('''
    connect correlate consult speak talk play fight work
''') | set('''
    consistent compatible compatibility connection connections correlation
    association relations relationship relationships conjunction collaboration
    interaction interactions engagement partnership intersection consultation
    conversation conversations dialogue cooperation love touch aligned spoke
    compliance accordance border equipped armed identified related adorned
    satisfied pleased shared paired tasked closely experimenting
'''.split())
SUPPORT_AND_COMBINATION = inflections('start agree assist cooperate') | set('''
    along together agreement combined mixed coupled fitted provided supplied
    covered replaced involved comfortable happy satisfaction help experience
    experiment issue issues discussion discussions communication parallel
    harmony friends common ended begin begins beginning began do
'''.split())
TREATMENT = set('''
    treated stained loaded packed lined infected decorated charged born
    patients students problems wrong share mix
'''.split())


def prose_with(before):
    if not before.strip() or before.endswith(('\n', '\t', '  ')):
        return 0.82
    if before.rstrip().endswith((',', ';', ':')):
        return 0.73
    match = re.search(r'([A-Za-z]+)$', before)
    word = match[1].lower() if match else ''
    if word in FAMILIARITY:
        return -0.42
    if word in ENGAGEMENT:
        return -0.26
    if word in ASSOCIATION:
        return -0.15
    if word in RELATION:
        return 0.0
    if word in SUPPORT_AND_COMBINATION:
        return 0.15
    if word in {'you', 'yourself', 'us', 'me', 'himself'}:
        return 0.14
    if word in TREATMENT or word in {'him', 'her', 'them', 'up', 'around'}:
        return 0.25
    if word in {'out', 'down', 'done', 'left', 'ends', 'combination'}:
        return 0.34
    if word in {'and', 'but', 'or', 'as', 'even', 'called', 'finished'}:
        return 0.76
    if word == 'completed':
        return 0.65
    if word.endswith(('ed', 'ing')):
        return 0.39
    return 0.52


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\n_(.\"-')
    if word.lower() == 'with':
        if word == 'With':
            value = 0.98 if token.startswith(' ') else 1.08
        elif word == 'WITH':
            value = 0.50 if token.startswith(' ') else 0.90
        elif token == ' with':
            value = prose_with(before)
        else:
            value = 0.78 if token in {'with', '_with'} else 0.98
    elif word.lower() == 'of':
        if word == 'Of':
            value = 0.37 if token.startswith(' ') else 0.52
        elif word == 'OF':
            value = 0.16 if token.startswith(' ') else 0.55
        else:
            value = 0.0 if token.startswith(' ') else (0.18 if token == 'of' else 0.40)
    elif token in {' con', ' avec', ' với'}:
        value = 0.19
    elif token in {' using', 'using', ' without', 'without'}:
        value = -0.07
    elif token in {' along', ' together'}:
        value = 0.07
    else:
        value = 0.0
    return (doc, (before + token)[-64:]), float(value)

"""A lexical balance detector, not a computation of whether things balance.

Balance spellings (including partial spellings in names) respond strongly;
words linking two sides respond less strongly. A short text tail recognizes
split spellings and phrases such as 'balance between' and 'balance of'.
There is also a negative response when byte fragments finish certain
unusual typographic spaces, primes, or the historical long s.
"""
import re

READS = ()
BALANCE_FORMS = {
    'balance': 5.6, 'balances': 5.6, 'balancing': 5.6, 'alance': 5.6,
    'balanced': 3.65, 'balancer': 3.4, 'balancers': 3.4,
}
RELATIONS = {
    'between': 1.5, 'etween': 1.5, 'между': 1.5, 'بين': 1.5,
    'entre': 1.0, 'zwischen': 1.0, 'both': 0.9, 'against': 0.86,
    'within': 0.35, 'equilibrium': 0.85, 'flexible': 0.67,
    'flexibility': 0.49, 'symmetry': 0.34, 'tension': 0.4,
}
TRANSLATIONS = {'平衡': 4.8, '不平衡': 3.7, '衡': 6.5,
                '均衡': 2.2, '余额': 3.5, 'バランス': 3.5}
CONNECTION = set('relationship connection association link overlap'.split())
COMPARISON = set(('difference differences distance distances angle comparison '
                  'correlation interaction interactions relation similarity '
                  'similarities').split())
SEPARATION = set(('gap gaps space line lines area boundary boundaries conflict '
                  'contrast distinction separation').split())
# Only when these characters are completed by a byte-fragment token.
TYPOGRAPHY = {
    '\u2003': -1.05, '\u2009': -1.05, '\u200a': -1.05,  # Em/thin/hair spaces.
    '\u2002': -0.45, '\u202f': -0.45,  # En/narrow no-break spaces.
    '\u200d': -1.7, 'ſ': -0.75, '′': -0.5, '″': -1.85,
}


def last_word(text):
    match = re.search(r'[a-zA-Z]+$', text)
    return match.group().lower() if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.strip('_./-').lower()
    previous = last_word(tail)
    current = last_word(tail + token)
    spaced = token[:1].isspace()
    value = RELATIONS.get(word, TRANSLATIONS.get(raw, 0.0))

    if current.endswith(('imbalance', 'imbalances', 'unbalanced')):
        value = 2.6
    elif word in BALANCE_FORMS:
        value = BALANCE_FORMS[word]
        if word in {'balance', 'balances', 'balancing', 'alance'}:
            value = 5.6 if spaced else 4.9
            if raw[:1] in '_./-':
                value = 4.0
            elif raw[:1].isupper():
                value = 5.1
        elif word == 'balanced' and not spaced:
            value = 3.0
    elif current.endswith('balanced'):
        value = 3.65 if spaced else 3.0
    elif current.endswith('balanc'):
