STRONG_DEGREE = {'very', 'too', 'rather'}
PERSONAL_STANCE = {'need', 'want', 'think', 'believe', 'hope', 'feel', 'might'}
SOURCE_DIRECTORIES = {'workspace', 'test', 'fixtures', 'spec', 'local'}


