        elif w in PERSONAL_STANCE:
            value = 0.049
        elif w == 'nothing':
            value = -0.126
        elif w == 'almost':
            value = -0.106
    if word == '二':  # The Chinese numeral two.
        value = 0.178
    elif word == '月':  # The month/moon ideograph.
        value = 0.085
    elif word == '(AdapterView':  # An Android adapter-backed view type.
        value = -0.56
    elif token.startswith('/') and word[1:] in SOURCE_DIRECTORIES:
