"""Approximate the component's dominant negative signal for user vocabulary.

Recognize singular and plural user words, user-name/ID conventions, and a
small multilingual user lexicon. Case and attached opening punctuation adjust
their strengths; 'used' and customer words get small negative values.
A chat-role 'user' is weaker at document start and stronger later. Predict
small continuations on following newlines and common user phrases. Reset at
document boundaries, and predict zero elsewhere. Smaller unrelated lexical
and context-dependent activations are deliberately left unexplained.
"""
READS = ()

# User words and recognizable stems in other languages.
USER_WORDS = {
    '用户': -5.6, '用戶': -4.5, '用户的': -4.2,
    'пользоват': -4.1, 'пользователя': -2.5, 'ользоват': -1.4,
    'usuario': -3.2, 'usuarios': -2.1, 'usuário': -3.0,
    'utilisateur': -2.5, 'użytk': -2.1, 'utzer': -1.8,
    'ユーザー': -3.4, 'ユーザ': -3.5, '使用者': -1.25,
}


def word_signal(token):
    raw = token.strip()
    word = raw.lstrip('._-/(:"=$[<\\')
    lower = word.lower()
    spaced = token[:1].isspace()
    if lower == 'user':
        if raw.startswith(('(', '"', '=', '[', '<')):
            return -4.3 if word == 'User' else -3.75
        if word == 'User':
            return -5.85 if spaced else -6.25
        return -5.3 if word == 'USER' else -5.4
    if lower == 'users':
        if word == 'USERS':
            return -3.3
        if word == 'Users' and not spaced:
            return -4.6
        return -4.1 if spaced else -3.5
    if lower.startswith('username') or lower == 'userid':
        return -1.8
    if lower == 'usr':
        return -1.25
    if word in ('getUser', 'setUser'):
        return -4.0
    if word.endswith('User') or (lower.startswith('user') and word[4:5].isupper()):
        return -2.5
    if lower in USER_WORDS:
        return USER_WORDS[lower]
    if lower == 'used':
        return -0.41 if spaced else -0.3
    if lower in ('customer', 'customers'):
        return -0.9 if lower == 'customer' else -0.48
    if word == '客户':
        return -0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, history = 0, ('', '', '')
    else:
        _, position, history = carry
        position += 1
    oldest, before, previous = history
    token = prefix.token_strings[-1]
    value = word_signal(token)
    if token == 'user' and previous == '<|im_start|>':
        if position == 1:
            value = -4.66
        elif position < 10:
            value = -5.6
        else:
            value = -6.65 if position < 30 else -6.85
    elif token == '\n' and previous.strip().lower() in ('user', 'users'):
        if previous == 'user' and before == '<|im_start|>':
            value = -1.11 if position == 2 else -0.7
        else:
            value = -1.25 if position == 1 else -0.75
    elif (token == '\n' and previous == '<tool_response>'
          and before == '\n' and oldest == 'user'):
        value = -0.5 if position == 4 else -0.2
    elif previous.strip().lower() in ('user', 'users'):
        value = {' of': -1.25, ' interface': -0.28,
                 ' experience': -0.55}.get(token, value)
    return (doc, position, (before, previous, token)), float(value)

