"""Component layers.0.mlp.down_proj:5898: a "user" word detector.

Layer 0's MLP writes a strong negative signal into the residual stream whenever the
current token is the word "user" in any capitalisation or spacing ("user", " user",
"User", "USER", "-user", "_USER"). It is silent on nearly every other token, so the
program predicts 0 except on a short list of user-related words.

Sizes, as the component's activation (negative = the "user" direction):
- "user" right after a chat-role marker ("<|im_start|>user", the speaker label of a
  chat turn) is the strongest case, about -6.9. If that marker directly follows
  "<|endoftext|>", i.e. it opens a new document, it is weaker, about -4.7.
- "user" anywhere else (code identifiers, prose, "user interface") is about -5.5.
- the plural " users" is about -4, the Chinese word 用户 ("user") about -5.5.
- "customer(s)" is weakly negative (about -0.8), "usr", "usuario" about -2.
- "username" is about -1.6 and " used" about -0.45.

Everything else is 0. The program is stateless: it reads only the current token and the
two before it.
"""

READS = ()

CHAT_MARKER = "<|im_start|>"
DOC_END = "<|endoftext|>"
USER_FORMS = {"user", " user", "User", " User", "USER", " USER", "-user", ".user", "_USER", ".User"}
USER_PLURAL = {" users", "users"}
USER_ZH = {"用户"}
CUSTOMER_FORMS = {" customer", " customers", "customer"}
USR_FORMS = {"usr", " usuario", " usuarios", "Usuario"}
USERNAME_FORMS = {"username", " username", "Username", " Username"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    token = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    before = toks[-3] if len(toks) > 2 else ""
    if token == "user" and prev == CHAT_MARKER:
        value = -4.7 if before == DOC_END else -6.9
    elif token in USER_FORMS:
        value = -5.5
    elif token in USER_PLURAL:
        value = -4.0
    elif token in USER_ZH:
        value = -5.5
    elif token in USR_FORMS:
        value = -2.0
    elif token in USERNAME_FORMS:
        value = -1.6
    elif token in CUSTOMER_FORMS:
        value = -0.8
    elif token == " used":
        value = -0.45
    else:
        value = 0.0
    return carry, value

