def step(carry, prefix, upstream):
    surface = prefix.token_strings[-1].casefold()
    token = surface.strip()
    plain = token.strip(" \t\r\n,.;:!?()[]{}<>\"'`/\\")

    if "user" in token:
        if any(name in token for name in ("username", "userid", "userinput")):
            return None, -1.8
        if plain == "user":
            return None, -5.35 if surface.startswith(" ") else -6.2
        if plain == "users":
            return None, -4.2
        return None, -5.2

    if "用户" in token:
        return None, -5.5
    if "пользоват" in token:
        return None, -4.0
    if "usuario" in token:
        return None, -3.3
    if plain == "used":
        return None, -0.4
    if "customer" in token:
