"""Draft 6: after a comma (or similar clause punctuation), a lowercase word that opens a
continuation of the sentence is negative. Strength depends on the kind of word: relative and
subordinating connectors strongest, then coordinating conjunctions, prepositions, and
determiners/pronouns; other lowercase words weaker; capitalised words, digits and single letters ~0."""

READS = ()

WEAK_BOUNDARY = {";", " –", " —", "—", " -", " ("}
RELATIVE = {" which", " who", " whom", " whose", " where", " while", " as", " with", " such",
            " including", " particularly", " especially", " though", " although", " whereas",
            " thereby", " resulting", " leading", " meaning", " along", " given", " according",
            " namely", " specifically", " consisting", " indicating"}
LINKER = {" and", " but", " or", " so", " yet", " not", " because", " since", " then", " if",
          " however", " even", " thus", " also"}
PREP = {" in", " for", " on", " at", " to", " by", " from", " of", " like", " when"}
DET_PRON = {" the", " a", " an", " we", " it", " you", " he", " she", " they", " I", " this",
            " there", " is", " was", " are", " these", " those", " his", " her", " their", " its",
            " our", " my", " your"}


def level(cur):
    if cur in RELATIVE:
        return -3.7
    if cur in LINKER:
        return -2.0
    if cur in PREP:
        return -1.7
    if cur in DET_PRON:
        return -1.0
    word = cur.strip()
    if cur[:1] == " " and len(word) > 1 and word.isalpha() and word.islower():
        return -0.5
    return 0.0


def after_comma(prev):
    # a comma, also inside a closing token such as '",' or '),'
    return prev.rstrip()[-1:] in (",", "，")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if after_comma(prev):
        return None, level(cur)
    if prev in WEAK_BOUNDARY:
        return None, 0.5 * level(cur)
    return None, 0.0

