READS = ()


def response(token, previous):
    w = token.strip()
    spaced = token.startswith(' ')
    if '\n' in previous or '\r' in previous:
        previous = ''
    brace = previous.endswith('}') and '{' not in previous
    inside = '}' in previous and not brace
    if brace:
        kind = 1
    elif previous.endswith(']'):
        kind = 2
    elif previous.endswith(')'):
        kind = 3
    else:
        kind = 0
    if w.lower().lstrip('._(/-') == 'from':
        if brace:
            return -6.85 if previous.startswith(' ') else -5.25
        if w[:1].isupper():
            return -0.7
        return (-0.57, -5.25, -1.6, -1.13)[kind] if spaced else -0.83
    if w in {'else', 'elseif', 'catch', 'finally', 'while'}:
        if w == 'while':
            return -2.0 if brace else 0.0
        if brace:
            if '\t' in token or '\n' in token:
                return -0.8
            if not token[:1].isspace():
                return -4.2
            return -3.4 if previous.startswith(' ') else -2.6
        return -0.3
    if '}' in token:
        return 0.14 if brace and previous.startswith(' ') else 0.0
    if '{' in token:
        if '\n' in token:
            return (0.09, -0.9, -0.08, -0.15)[kind]
        if w.startswith('^'):
            return (1.4, -2.2, -0.9, -0.1)[kind]
        if w.startswith('_'):
            return (0.9, -2.45, -0.6, -0.15)[kind]
        if brace:
            return -1.4 if spaced else -2.6
        if inside:
            return 0.0
        if '"' in token or "'" in token:
            value = 0.7
        else:
            value = 0.6 if spaced else 0.36
        return value if kind == 0 else 0.0
    if w.startswith('^'):
        values = (0.0, -3.5, -2.0, -0.84) if w == '^' else (0.1, -2.5, -1.1, -0.8)
        return values[kind]
    if w == '_':
        return (0.06, -2.7, -1.0, -0.17)[kind]
    if w in {'left', 'right'} and not token[:1].isspace():
        return -1.3 if inside else -0.55 if previous.endswith('\\') else -0.2
    if w == '\\':
        if inside:
            return -0.67
        return (0.0, -1.5 if spaced else -2.6, -0.65, -0.18)[kind]
    if w in {'(\\', '[\\', '+\\', '-\\', ';\\', '\\\\'}:
        return (0.0, -1.7, -0.3, -0.3)[kind]
    if w in {'+', '-', '*', '/', '=', '&', '|', '<', '>', '//', '/*'}:
        return (0.0, -1.7, -0.8, -0.3)[kind]
    if w in {'(', '['}:
        return (0.0, -1.3 if spaced else -2.8, -0.8, -0.1)[kind]
    if not w:
        return (0.0, -0.2 if '\n' in token else -0.75, -0.22, 0.1)[kind]
    if '\n' in token or token.startswith('<|'):
        return -0.15 if brace else 0.0
    if inside:
        return -0.3
    return (0.0, -0.45 if spaced else -1.0, -0.18, 0.0)[kind]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(token, previous))

