"""Layer-0 MLP down-projection, component 5900: a "keyword right after a closing brace" detector.

What it does, in plain terms. The component is mostly silent. Its strong responses come on
the token that directly follows a closing brace `}` when that token continues the code or
formula rather than ending the statement:
  - `} from`  (JS/TS `import { x } from ...`)      strongly negative, about -6
  - `} else`, `} catch`                              negative, about -3
  - `}^`, `}_`  (LaTeX super/subscripts)             negative, about -2.8
  - `}{`, `}(`, `}[`                                 negative, about -1.7
  - `}\\`, `}+`, `}=`, `}&`, other operators       negative, about -1.1 to -1.4
  - whitespace, `}`, `)`, `<`, `$` after `}`        about zero
  - a plain word after `}`                           weakly negative, about -0.3
Elsewhere it is weakly negative on the word "from" (about -0.6) and "else" (about -0.4),
and weakly positive on opening braces, most of all LaTeX `^{` and `_{` (about +1.0) and
other `{` (about +0.5). Everything else is about zero.

Why: the component's activation is dominated by these few tokens; a lookup on
"previous token closes a brace" plus the next token's identity captures most of its
variance. The values are rounded group means measured on training text.
"""

READS = ()


def _word(tok):
    return tok.strip(" \t\n_.").lower()


def _after_close(tok):
    """Value for a token right after a closing brace."""
    s, w = tok.strip(), _word(tok)
    if w == "from":
        return -6.3
    if w in ("else", "catch", "elseif"):
        return -3.0
    if s[:1] in ("^", "_") and s:
        return -2.8
    if s[:1] in ("{", "(", "[") and s:
        return -1.7
    if s[:1] == "\\" or w in ("left", "right"):
        return -1.4
    if s[:1] in ("+", "-", "=", "&", "*") and s:
        return -1.1
    if not s or s[:1] in "}])<$/#.`\"';,:":
        return -0.15
    if w.isalpha():
        return -0.3
    return -0.75


def _elsewhere(tok):
    """Value for a token that does not follow a closing brace."""
    s, w = tok.strip(), _word(tok)
    if w == "from":
        return -0.6
    if w in ("else", "catch", "elseif"):
        return -0.4
    if "{" in s:
        return 1.0 if s[:1] in ("^", "_") else 0.5
    if s in ("^", "_"):
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if prev.rstrip(" \n\t").endswith("}"):
        value = _after_close(tok)
    else:
        value = _elsewhere(tok)
    return carry, float(value)

