        score = -0.72
    elif token == "</":
        score = 0.38
    elif token in ("http", "https"):
        score = -0.3 if token == "http" else -0.37
    elif token == "://":
        score = -0.25
    elif token == "&apos":
        score = -0.27
    elif token == ";s" and previous and previous[-1] == "&apos":
        score = -0.4
    elif token == "3" and len(previous) >= 1 and previous[-1] == "&#":
