"""Short z-bearing letters and syllables, with a small echo inside words.

Script and case set the strength of isolated z-like letters. Short fragments
are weaker; common vowel combinations differ, and longer words usually have
little response. An isolated letter is stronger at a document's first token.
The previous fragment contributes a small echo only on word continuations.
This is an orthographic approximation, not a phonetic transcriber.
"""
READS = ()

# Each z-like letter: ordinary token, space-led token, document-first token.
Z_LETTERS = {
    'z': (0.9, 1.3, 2.2),
    'Z': (1.4, 1.6, 3.8),
    'з': (4.1, 4.1, 7.6),
    'З': (5.1, 5.1, 9.0),
    'ز': (3.8, 3.8, 6.3),
    'ζ': (2.8, 2.8, 2.8),
    'Ζ': (2.8, 2.8, 2.8),
    'ז': (2.8, 2.8, 2.8),
    'ず': (2.1, 2.1, 2.7),
    'ズ': (2.1, 2.1, 4.1),
    '지': (1.0, 2.9, 1.5),
}
VOWELS = 'aeiouy'


def token_response(token, first=False):
    spaced = token[:1].isspace()
    letters = ''.join(c for c in token if c.isalpha())
    text = letters.lower()
    n = len(text)
    if letters in Z_LETTERS:
        ordinary, space_led, initial = Z_LETTERS[letters]
        if first:
            return initial * (0.8 if spaced else 1.0)
        if text == 'z' and ('/' in token or '-' in token):
            return 1.9 if letters.isupper() else 1.6
        return space_led if spaced else ordinary
    if not n:
        return 0.0

    if 'з' in text:
        if n == 2:
            if text in ('ез', 'оз'):
                return 3.8
            if text == 'за':
                if letters[0].isupper():
                    return 3.5
                return 2.45 if spaced else 2.05
            return 1.4 if text == 'из' and spaced else 1.7
        if text == 'раз':  # The common Russian prefix/word raz.
            return 0.1
        if n <= 5 and text.endswith(('ез', 'оз')):
            return 1.4
        if n <= 5 and text.endswith('з'):
            return 0.45
        if n <= 5 and text.startswith('за'):
            return 1.0
        return 1.25 if n == 3 else 0.1
    if 'ز' in text:
        if text == 'الز':  # The Arabic article al- followed by z.
            return 3.0
        return 2.3 if n == 2 else 0.9 if n == 3 else 0.3
    if any(c in text for c in 'ざザぜゼぞゾじジずズ'):
        return 0.4 if text in ('じ', 'ジ') or n > 1 else 1.0
    if '즈' in text:
        return 1.1
    if 'ذ' in text:
        return 0.3
    if 'z' not in text:
        return 0.0

    if n == 2:
        if text.endswith('z'):
            if text == 'iz':
                return 0.0
            return 1.2 if text == 'oz' else 0.9 if text == 'ez' else 0.55
        if spaced:
            return 1.65 if text == 'ze' else 0.3 if text == 'zu' else 0.9
        return 0.5 if text[1] in VOWELS else 0.25
    if n == 3:
        if text.startswith('z'):
            if text[-1] in VOWELS:
                return 0.45
            return 0.7 if text[1] == 'a' else 0.15
        if text.endswith('z'):
            if text[-2] in 'eo':
                return 0.9 if spaced else 0.6
            return 0.2 if text[-2] not in VOWELS else 0.4
        return 0.2
    if text.startswith('z'):
        if text.startswith('zero'):
            return 0.05
        return 0.75 if n == 4 and text[-1] in VOWELS else 0.3
    return 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    base = token_response(token, first)
    value = base
    if not first and token[:1].isalpha():
        cyrillic = '\u0400' <= token[0] <= '\u04ff'
        value += (0.17 if cyrillic else 0.10) * carry[1]
    return (doc, base), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:5903 fires on the letter z written in any script.

It is a token detector. Its activation is large when the current token is a short
fragment (one or two letters, a leading space ignored) whose letter is z-like:

  * Cyrillic з / З (the z sound of Russian), and the look-alikes ζ (Greek) and ز (Arabic):
    strongest, about 3;
  * Latin z / Z: about 1.

Two things scale that strength down:
  * length: a z-letter in a 3-character token counts 0.4 of its strength, in a longer
    token 0.1. A long Russian word that contains з (произвести, различие) barely fires.
  * position: the z-letter at the start of the token counts fully, at the end 0.7, and
    in the middle 0.5.

Everything else predicts 0. The program keeps no state: it reads only the newest token.
"""

READS = ()

Z_STRENGTH = {"з": 3.0, "З": 3.0, "ζ": 3.0, "ز": 3.0, "z": 1.0, "Z": 1.0}
Z_LETTERS = set(Z_STRENGTH)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    strength = max((Z_STRENGTH.get(ch, 0.0) for ch in token), default=0.0)
    if len(token) <= 2:
        length_factor = 1.0
    elif len(token) == 3:
        length_factor = 0.4
    else:
        length_factor = 0.1
    if not token or strength == 0.0:
        position_factor = 0.0
    elif token[0] in Z_LETTERS:
        position_factor = 1.0
    elif token[-1] in Z_LETTERS:
        position_factor = 0.7
    else:
        position_factor = 0.5
    return carry, float(strength * length_factor * position_factor)

programs.sol:
"""A heuristic for rare Unicode and encoding-boundary responses.

Large positives mark mojibake-shaped legacy-encoding transitions, C1
controls, and detached Latin-1 UTF-8 lead bytes. Incomplete Indic and
Hebrew/Arabic prefixes get smaller positives. Typography and extended
Latin letters depend on preceding character classes. Nonbreaking
spaces after dashes and footnote daggers after uppercase ASCII tokens
get extra weight; selected document-initial symbols get a boost.
Selected hex-escape and numeric-entity prefixes get small positives. ASCII word fragments after
Latin-range non-ASCII letters get a small negative value. Other tokens
get zero. All state resets at document boundaries.

This captures encoding/typography responses, not the component's many
small activation differences among ordinary words.
"""
import unicodedata as ud

READS = ()
# First 256 Qwen byte tokens: printable bytes, then the remaining bytes.
_PRINTABLE = list(range(33, 127)) + list(range(161, 173)) + list(range(174, 256))
_BYTE_ORDER = _PRINTABLE + [b for b in range(256) if b not in _PRINTABLE]

# Exact two-byte UTF-8 prefixes for U+0900-U+0DFF, as Qwen tokens.
INDIC_PREFIXES = frozenset({
    5502, 12619,       # Devanagari
    11125, 26927,      # Bengali
    39317, 65877,      # Gurmukhi
    40714, 72219,      # Gujarati
    124593,            # Oriya
    20026, 31501,      # Tamil
    31305, 52798,      # Telugu
    33556, 55890,      # Kannada
    33739, 50111,      # Malayalam
    54642, 48749,      # Sinhala
})


def encoding_transition(previous, current):
    """Return a legacy continuation byte for a mojibake-shaped transition."""
    if not previous or current.isascii():
        return 0
    for encoding in ('cp1252', 'latin1', 'cp1250', 'cp1251'):
        try:
            first = current[0].encode(encoding)[0]
            last = previous[-1].encode(encoding)[0]
        except UnicodeError:
            continue
        if not 0x80 <= first <= 0xbf:
            continue
        # Avoid mistaking natural Cyrillic letters or quotes for mojibake.
        if encoding == 'cp1251' and ord(current[0]) > 255 and first >= 0xa0:
            continue
        if encoding == 'cp1251' and (
                (last == 0xe2 and first != 0x80)
                or (last == 0xf0 and first != 0x9f)):
            continue
        if last == 0xef and first == 0xac:
            return first
        if last in (0xc2, 0xc3, 0xc4, 0xc5, 0xd0, 0xd1, 0xe2, 0xf0):
            return first
        if len(previous) > 1 and 0x80 <= last <= 0xbf:
            try:
                if previous[-2].encode(encoding)[0] in (0xe2, 0xef, 0xf0):
                    return first
            except UnicodeError:
                pass
    return 0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, tail, last_byte, last_value = ('', '', -1, 0.0)
    if carry is not None and carry[0] == doc:
        _, previous, tail, last_byte, last_value = carry
    tid = prefix.token_ids[-1]
    byte = _BYTE_ORDER[tid] if 0 <= tid < 256 else -1
    nonascii = any(ord(c) > 127 for c in previous)
    mark = any(ord(c) > 127 and ud.category(c)[0] in 'PSMZN'
               for c in previous)
    continuation = encoding_transition(tail, s)
    if tid in INDIC_PREFIXES:
        value = 0.55
    elif byte == 0xc2:
        value = 3.5 if nonascii else 0.7
    elif byte in (0xd6, 0xd7, 0xd9, 0xdb):  # Hebrew/Arabic prefixes
        value = 0.65 if byte == 0xd6 else 0.35
    elif any('\x80' <= c <= '\x9f' for c in s):
        value = 3.5 if nonascii else 0.5
    elif s == '€™':  # A common corrupted apostrophe fragment
        value = 3.0
    elif s == '�' and last_byte == 0xc2:
        value = 1.0 if last_value > 2.0 else 0.2
    elif continuation:
        value = 2.6 if continuation < 0xa0 else 1.6
    elif s == '\\xa':
        value = 0.34
    elif s.lstrip(' ') in {'&#', '&#x'}:
        value = 0.2
    elif s == '··':
        value = 0.65 if mark else 0.05
    elif s.strip(' ') == '©':
        value = 0.75
    elif s == '\xa0':
        value = -0.04 + 0.47 * mark
        if previous == s:
            value = 0.24
        elif previous.rstrip().endswith(('–', '—')):
            value = 0.65
        elif previous and previous.isascii() and previous.isspace():
            value = -0.1
    elif len(s) == 1 and (s in '¹²³' or '\u2070' <= s <= '\u209f'):
        value = -0.05 + 0.4 * mark
    elif s in {'†', '‡'}:
        value = (0.3 if s == '†' else 0.65) + 0.35 * mark
        if previous.strip().isascii() and previous.strip().isupper():
            value = 0.65
        elif previous and previous.isspace():
            value = 0.0
    elif len(s) == 1 and s in '±µ°·®™':
        base = 0.2 if s == '±' else 0.15 if s == 'µ' else 0.05
        value = base + 0.5 * mark
        if s in '®™':
            value += 0.15
    elif len(s) == 1 and '\xa1' <= s <= '\xbf':
        value = 0.4 if mark else -0.03
    elif len(s) == 1 and not s.isascii() and 'LATIN' in ud.name(s, ''):
        latin_before = bool(previous) and (
            not previous[-1].isascii() and 'LATIN' in ud.name(previous[-1], ''))
        value = 0.25 if mark or latin_before else 0.0
        if not previous:
            value = 0.35
    elif (s.isascii() and s.isalpha() and previous
          and 127 < ord(previous[-1]) < 0x250
          and previous[-1].isalpha()):
        value = -0.1
    elif s == '\ufe0f':
        value = 0.15
    else:
        value = 0.0
    if (not previous and len(s) == 1
            and (s in '¹²³±µ°·†‡®™€£¥¤' or 0xa1 <= ord(s) <= 0xbf)):
        value = 1.1
    return (doc, s, (tail + s)[-4:], byte, value), float(value)

