"""Candidate 7: after a first-person subject ("I", "we"), the next word is read for stance.
Future auxiliaries ("will", "'ll", "won") and announcing verbs ("say", "suggest", "mean",
"present", "tell", "hope"...) push the activation negative; be-verbs and knowledge or
perception verbs ("am", "was", "know", "understand", "see"...) push it positive. A "you" that
is the object of an announcing verb ("tell you", "give you") is negative too. Everywhere
else it is 0."""

READS = ()

FIRST_PERSON = {"I", "we", "We"}
FUTURE = {"will", "'ll", "’ll", "won"}
MODAL = {"would", "'d", "’d", "should", "shall", "must", "may"}
ANNOUNCE = {"say", "said", "suggest", "propose", "recommend", "mean", "tell", "show", "present",
            "describe", "mention", "offer", "provide", "share", "submit", "conclude", "give",
            "gave", "grant", "call", "apologize", "repeat", "hope", "wish", "argue", "advise",
            "assure", "remind", "let"}
KNOW = {"know", "knew", "understand", "remember", "read", "heard", "hear", "see", "saw", "notice",
        "noticed", "learned", "liked", "loved", "missed", "feel", "realize", "recall"}
BE = {"am", "'m", "’m", "are", "'re", "’re", "is", "was", "were"}
HAVE = {"have", "had", "got", "get"}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return carry, 0.0
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip()
    if before in FIRST_PERSON:
        if word in FUTURE:
            return carry, -3.5 if before == "I" else -2.0
        if word in MODAL:
            return carry, -1.2
        if word in ANNOUNCE:
            return carry, -2.0
        if word in KNOW:
            return carry, 1.8
        if word in BE:
            return carry, 1.0
        if word in HAVE:
            return carry, 0.5
        return carry, 0.0
    if word in ("'t", "’t") and before == "won":
        return carry, -0.7
    if word == "you" and before in ANNOUNCE:
        return carry, -1.5
    return carry, 0.0

