    history = context + before
    opening = history.rfind('<')
    tag = history[opening + 1:] if opening > history.rfind('>') else ''
    closing = tag.startswith('/')
    label = tag[1:] if closing else tag
    match = re.match(r'[A-Za-z][A-Za-z0-9_-]*', label)
    name = match.group() if match else ''

    if closing:
        return 0.75 if name.lower() in MARKUP_TAGS else 0.15
    if name.lower() in MARKUP_TAGS:
