FRENCH = set('le les la de des du et une un est que dans pour avec sur pas '
             'au aux il elle vous nous mais ne sont cette'.split())
ENGLISH = set('the and is of for to with that are this in a an it from by be'.split())
# Operator and quantity words, including common translations.
OPERATORS = {
    'subtract': 1.0, 'subtraction': 0.97,
    'divided': 0.32, 'multiplied': 0.53, 'multiply': 0.24,
    'squared': 0.67, 'percent': 0.68, 'percentage': 0.71,
    'equal': 0.18, 'power': 0.22, 'number': 0.10,
    'versus': 0.70, 'excluding': 0.94, 'less': 0.22,
    'bonus': 0.50, 'modulus': 0.73, 'modulo': 0.55,
    'più': 0.90, 'meno': 1.0, 'moins': 1.53,
    'más': 0.41, 'menos': 0.92, 'mais': 0.26,
    '加': 1.25, '加上': 2.30, '减': 1.61, '減': 1.30,
    '乘': 0.75, 'プラス': 3.0, 'бонус': 1.14,
    '及': 0.92, '以及': 0.83, '还有': 0.89, '還有': 0.88,
