        carry = (doc, '', 0.0)
    _, previous_token, french = carry
    previous = previous_token.strip().lower()
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lower()
    operator = word.lstrip('_.-')
    value = OPERATORS.get(word, 0.0)
    if operator == 'plus':
        if bare == '-plus':
            value = 8.6
        elif bare.lstrip('_.-') == 'Plus':
            value = 7.7
        elif bare.lstrip('_.-') == 'PLUS':
            value = 6.6
        else:
            value = 4.4 if french > 0.5 else 7.0
        if previous == 'non':
            value = 3.1
        elif token == 'plus' and previous.endswith('sur'):
            value = 3.0  # Completing 'surplus'.
    elif operator == 'minus':
        value = 1.45 if previous in ('set', '\\set') else 5.1
        if token == 'minus' and previous == 'ter':
            value = 2.75  # Completing 'terminus'.
    elif word == 'equals':
        value = 1.91 if token.startswith(' ') else 1.4
    elif word == 'times':
        value = 0.84 if token.startswith(' ') else 0.27
        if previous.isdigit():
            value = 1.10
        elif previous in ('many', 'several', 'few', 'multiple', 'at', 'all'):
            value = 0.52
    elif '+' in token:
        formula_end = (previous.isdigit() or len(previous) == 1
                       or previous.endswith((')', ']', '}', '²')))
        if '+=' in token or ('++' in token and any(c in token for c in ');{')):
            value = 0.05
        elif bare == '++':
            value = 0.44
        elif any(c.isalpha() for c in token):
            value = 0.52
        elif token.endswith('\n'):
            value = 0.51
        elif token == ' +':
            value = 0.55 if formula_end else 0.76
        elif token == '+':
            value = 1.03 if previous_token.endswith('\n') else 0.80
        else:
            value = 0.70
    elif '±' in token or '＋' in token:
        value = 0.76 if '±' in token else 1.07
    elif word == 'to' and previous in ('equal', 'equals'):
        value = 0.76 if previous == 'equal' else 0.61
    elif word == 'by' and previous in ('divided', 'multiplied'):
