"""Layer-0 MLP down_proj component 5922: a German case-article detector.

The component is silent in most text. Inside German passages it goes negative on
case-marked German articles and article contractions (genitive/dative "des", "dem",
"im" most strongly; "am", "vom", "zum", "der", "den", "einem", ... less), and on German
inflection endings split off as their own tokens (-en, -em, -er, -es, -chen). It goes
mildly positive on a handful of German function words and verb-stem fragments (bei, zu,
war, sich, dabei, sei, lie-, hi-). Outside German it does nothing: "des" in French or
"der" in Danish leave it at zero.

"German passage" is a simple count: at least 4 common German function words among the
last 30 tokens of the same document.
"""

GERMAN_WORDS = set(
    """der die das den dem des ein eine einen einem einer eines und ist nicht mit auf
    für von zu im am vom zum bei aus nach wird werden sind hat haben oder aber wenn dass
    daß noch nur so wie als vor über um durch an in sein seine seiner dann doch schon
    sich auch wir ich es er sie ihr ihre ihrem ihren""".split()
)
STRONG_ARTICLES = {"des", "dem", "im"}  # genitive/dative, strongest
CASE_ARTICLES = {"am", "vom", "zum", "der", "den", "einem", "einer", "eines", "das", "es", "er", "man"}
ENDINGS = {"en", "em", "er", "es", "e", "ten", "chen", "igen", "enden", "ene", "enes", "ter", "ende"}
POSITIVE_WORDS = {"bei": 1.5, "zu": 0.7, "war": 1.3, "sich": 0.6, "dabei": 2.2, "sei": 2.2}
POSITIVE_FRAGMENTS = {"ß", "icht", "ü", "lie", "hi", "zie"}
WINDOW = 30
MIN_GERMAN_WORDS = 4

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    strings = prefix.token_strings
    token = strings[t]
    word = token.strip().lower()
    lo = max(0, t - WINDOW + 1)
    while lo < t and docs[lo] != docs[t]:
        lo += 1
    german = sum(strings[i].strip().lower() in GERMAN_WORDS for i in range(lo, t + 1))
    if german < MIN_GERMAN_WORDS:
        return carry, 0.0
    if token.startswith(" "):
        if word in STRONG_ARTICLES:
            return carry, -2.5
        if word in CASE_ARTICLES:
            return carry, -1.2
        if word in POSITIVE_WORDS:
            return carry, POSITIVE_WORDS[word]
    else:
        if token in ENDINGS:
            return carry, -0.8
        if token in POSITIVE_FRAGMENTS:
            return carry, 1.2
    return carry, 0.0

