"""Approximate a negative response to opening quotes and string literals.

Use whitespace/opening syntax and the immediately preceding token as clues.
Increase the magnitude when a quote and its initial word, path, format marker
or markup share a token. Suppress contractions, code fences, and most closing
marks. This is a local text heuristic, not a full quotation parser; it leaves
small word-specific responses unmodeled.
"""
READS = ()
QUOTES = '"\'`“‘「『《«'
CONTRACTIONS = {"'s", "'t", "'d", "'m", "'ll", "'re", "'ve"}


def predict_token(s, previous):
    if not s or s in CONTRACTIONS:
