            return -0.69 if q == '`' else (-1.14 if q == "'" else -0.97)
        if previous and previous[-1] in '.!?;)]}':
            return -0.05 if q == '`' else -0.4
        return 0.02 if q == '`' else -0.72
    if s in ('"', "'"):
        if previous and previous[-1].isspace():
            return -0.32 if previous.endswith('\n') else -0.75
        return 0.08
    marks = [(s.index(q), q) for q in QUOTES if q in s]
    if not marks:
        return 0.0
    i, q = min(marks)
    before, rest = s[:i], s[i + 1:]
    opening = (q in '“‘「『《«' or before[:1].isspace() or
               before.rstrip('\\').endswith(('(', '[', '{', '=')))
    if before == '\\':  # Escaped quotes in serialized text.
        return -0.84 if rest.startswith('\\') else (-0.4 if not rest else 0.0)
    if len(s) == 3 and s[0] == s[-1] and s[1] in ':,':
        return -1.0 if s[1] == ':' else -0.6
    if not rest or rest[0].isspace():
        if not opening:
            return 0.0
        if q in '`«':
