    if rest[0] == q:
        return -1.0 if opening else 0.0
    if not opening and (before or rest[0] in '.>?!' or '\n' in rest):
        return 0.0

    # Initial literal content: paths, formatting/template markers, markup,
    # grouping punctuation, and escapes/identifier punctuation.
    strength = 4.5
    if rest.startswith('</'):
        strength = 3.5
    elif rest.startswith(('../', '//', '--', '__')):
        strength = 6.2
    elif rest[0] in '$%@#<&{':
        strength = 6.1
    elif rest[0] == '/' or rest.startswith('./'):
        strength = 5.3
    elif rest[0] in '\\_+':
        strength = 4.0
    elif rest[0] == '.':
        strength = 3.3
    if not opening:
        strength *= 0.8 if rest[0] == '{' else 0.5
    if q == '`':
        strength = (4.3 if rest[0] == '_' else
                    2.7 if rest[0] in '[{(' else strength * 0.75)
    if '$(' in before or (q in rest and not rest.startswith('\\' + q)):
        strength *= 0.8 if rest[0] == '{' else 0.55
    return -strength


