READS = ()

# Familiar TeX commands (or the first fragment of a longer command).
TEX_MARKUP = {
    'begin': 0.95, 'end': 2.6,
    'nu': 1.2, 'new': 1.2, 'near': 1.2, 'non': 2.4,
    'not': 1.2, 'notin': 1.2, 'neg': 1.2,
    'text': 0.75, 'display': 0.75, 'big': 0.75,
    'le': 0.8, 'ge': 0.8, 'right': 0.45, 'to': 0.5,
    'normal': 1.6,
