        if len(token) == 1 or token[1].isupper():
            value = 3.45
        elif token == 'ne':
            value = 3.6
        elif len(token) == 2:
            value = 4.3 if token[1] in 'aeiou' else 5.6
        else:
            value = 4.9
        slashes = len(previous) - len(previous.rstrip('\\'))
        value -= 0.95 * min(2, slashes - 1)
        before_slash = previous.rstrip('\\').rstrip()
        if before_slash.endswith(('.', ',', ';', '`')):
            value += 0.3
        elif before_slash.endswith(('(', '{', '[')):
            value -= 0.3
        return value
    if token.startswith('t') and len(token) <= 2:
        return 1.5 if len(token) == 1 or token[1] in 'aeiou' else 2.5
    if token == 'r':
        return 1.2
    if token.startswith('x') and len(token) > 1 and all(
            c in '0123456789abcdefABCDEF' for c in token[1:]):
        return 2.85 if token[1].lower() == 'e' else 1.95
    if token[0] == ')':
        return 1.8 if '.' in token else 2.5
    if token[0] == ']':
        return 0.6 if '.' in token else 1.4
    if token[0] in '{$':
        return -2.4
    if token[0] in '@~`':
        return -2.7
    if token[0] in '[,*#;&':
        return -1.4
    if token[0] == '"':
        return -1.4 if ',' in token else -0.45
    if token.isspace() or not token.strip(' \\'):
