    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if previous.endswith('\\'):
        value = after_backslash(token, previous)
    elif token == '\\n':
        value = 1.3
    elif token == '\\t':
        value = 0.8
    elif token in {'еб', 'еп', 'ек', 'ез'} and previous.strip().lower() == 'н':
        value = 1.8
    else:
        value = 0.0
