READS = ()
QUOTES = '"\'`“‘'
OUTPUT = {'print', 'printf', 'println', 'writeln', 'writeline', 'log',
          'errorf', 'fprintf', 'sprintf', 'puts', 'echo'}
TYPES = {'string', 'int', 'float', 'double', 'bool', 'boolean', 'char',
         'long', 'short', 'byte', 'void', 'object', 'struct', 'const'}
