SYMBOLS = {'$': 2.15, '!': 2.75, '&': 2.70, '*': 1.90, '|': 3.40,
           '/': 3.10, '@': 2.10, '#': 1.75, '^': 2.15, '<': 2.25,
           '+': 1.70, ':': 1.85, '-': 1.18, ';': 2.20, '>': 2.20,
           '.': 1.70, ',': 1.70}


def quoted_argument(rest, previous, spaced):
    escaped = rest.startswith('\\')
    quote = rest.lstrip('\\')[0]
    value = 3.30 if escaped else (3.80 if quote == "'" else 3.60)
    if not escaped and spaced:
        value = 3.85 if quote == '"' else 3.30
    elif not escaped and previous[:1].isupper():
        value += 0.20
    if previous.lower() in OUTPUT:
        value = 2.85 if escaped else 2.70
        if not escaped and previous.lower() in {'printf', 'println', 'writeline'}:
            value = 2.25
        if quote == '`':
            value = 3.20
    if not escaped and rest[1:].startswith('%'):
        value = 3.65  # format string
    elif not escaped and rest[1:].startswith('\\\\'):
        value = 3.55  # escaped text inside a string
    if ')' in rest:
