        return None, 1.20 if previous else 0.75
    if text.startswith('（'):
        return None, 0.54
    if len(text) > 1 and text[0] in '[{':
        if text[1] in QUOTES:
            return None, 0.79 if text[0] == '{' else (1.02 if spaced else 0.67)
        if text.startswith('[@'):
            return None, 0.62
    # Unary, assignment and macro markers can be merged before a quoted call.
    lead, opening, rest = text.partition('(')
    if not opening or any(ch not in '=!$>_' for ch in lead):
        return None, 0.0
    if lead and (not rest or rest[0] not in QUOTES + '\\[{(&'):
        return None, 0.0
    if not rest:
        value = 0.0 if spaced else (0.35 if '\n' in previous else 0.70)
    elif rest[0] == ')':
        value = 0.0
    elif rest.lstrip('\\')[:1] in QUOTES and rest.lstrip('\\'):
        value = quoted_argument(rest, previous.strip().lstrip('.'), spaced)
        value -= 0.75 if lead else 0.0
    elif rest[0] in '([{' and rest[1:2] in QUOTES and len(rest) > 1:
        value = 3.60 if rest[0] == '{' else 4.10
    elif rest[0] == '[':
        value = 2.85
    elif rest[0] == '{':
        value = 2.30
    elif rest[0] == '(':
        value = 4.10 if '[' in rest else (0.90 if spaced else 1.40)
        if ')' in rest:
            value = 2.15
    elif rest[0].isalpha() or rest[0] == '_':
        value = 1.0 + 0.055 * min(len(rest) - 1, 8)
        if rest.lower() in TYPES or rest in {'new', 'function'}:
            value = 1.65
        if rest in {'true', 'false', 'null', 'None', 'NULL', 'len', 'sizeof'}:
            value = 2.0
        if rest == 'String':
            value = 2.10
        if rest.startswith('_'):
            value = 1.80
    else:
        value = SYMBOLS.get(rest[0], 0.72 if spaced else 1.0)
        if spaced and rest[0] in '$!*/-':
            value -= 1.05 if rest[0] == '/' else 0.55
        if rest.startswith(('--', '++')):
            value += 1.0
    return None, float(value)

programs.haiku:
"""Open-parenthesis detector (layer-0 MLP feature 5926).

The component fires on the token that opens a round bracket with the first character of
its contents fused onto it: '("', "('", '(`', '($', '(x', '(\n'. The model sees one token at
a time, and that token already contains what follows the bracket, so the program reads the
token and looks at the characters after the bracket:

  - a quote or string opener ('"', "'", '`', curly quotes, '|'): strongest, about 3.3;
  - an escaped quote ('(\\"'): about 3.0; other backslashes: about 0.9;
  - a symbol ('[', '$', '&', '!', '<', '{', '*', '^', '@', '_', '#'): about 2;
  - a word, identifier or newline: about 1.1;
  - a bare '(' with nothing after it: about 0.7;
  - an empty call '()' (closing at once): 0.

A space, '!' or '$' before the bracket weakens a non-quote opener by a quarter, and a bare
' (' does not fire. Brackets '[' and '{' that open a quoted string ('{"', "['") fire weakly
(about 0.9). The fullwidth bracket '（' fires about 0.5. The end-of-text token also fires,
about 1.2. Everything else is 0.
"""

READS = ()

QUOTES = set("\"'`“‘|")
SYMBOLS = set("[$&!<{*^@_#")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "<|endoftext|>":
        return carry, 1.2
    if tok[:1] == "（":
        return carry, 0.5
    if tok[:1] in ("[", "{") and tok[1:2] in QUOTES:
        return carry, 0.9
    if tok[:2] in (" [", " {") and tok[2:3] in QUOTES:
        return carry, 0.8
    k = tok.find("(")
    if k < 0 or tok[:k] not in ("", " ", "!", "$"):
        return carry, 0.0
    body = tok[k + 1 :]
    if body == "":
        return carry, 0.0 if k else 0.7
    if body[0] == ")":
        return carry, 0.0
    if body[0] == "\\":
        value = 3.0 if body[1:2] == '"' else 0.9
    elif body[0] in QUOTES:
        value = 3.3
    elif body[0] in SYMBOLS:
        value = 2.0
    else:
        value = 1.1
    if k and body[0] not in QUOTES:
        value *= 0.75
    return carry, value

programs.luna:
"""Estimate a punctuation-sensitive activation concentrated at text boundaries.

End-of-text markers and open parentheses are the clearest cues; quoted and
structured code expressions after a parenthesis get the largest estimates.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()

    if token == "<|endoftext|>":
        return None, 1.2

    if token.startswith("("):
        following = token[1:]
        if following.startswith(('"', "\\", "'")):
            return None, 3.7
        if following.startswith(("/", "[", "{")):
            return None, 3.0
        if following.startswith("!"):
            return None, 2.3
        return None, 0.6 if not following else 1.0

    if token.startswith("（"):
        return None, 0.6
    if token.startswith("{\""):
        return None, 0.8

    return None, 0.0

"""Give punctuation-only tokens a small positive score, weighted by mark type."""
from unicodedata import category

READS = ()

ENDS = frozenset(".!?…。！？‼⁈⁉")
SEPARATORS = frozenset(",;:、，；：")
BRACKETS = frozenset("()[]{}<>（）［］｛｝〈〉《》「」『』【】")
QUOTES = frozenset("'\"`‘’“”«»‹›")
DASHES = frozenset("-‐‑‒–—―")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    marks = tuple(char for char in token if not char.isspace())

    if not marks or any(not category(char).startswith("P") for char in marks):
        return None, 0.0

    strength = 0.0
    for char in marks:
        if char in ENDS:
            strength = max(strength, 1.45)
        elif char in SEPARATORS:
            strength = max(strength, 1.25)
        elif char in BRACKETS or char in QUOTES:
            strength = max(strength, 0.55)
        elif char in DASHES:
            strength = max(strength, 0.4)
        else:
            strength = max(strength, 0.35)

    return None, float(0.083 * strength)

programs.sol:
"""A small mixed lexical readout, not a reliable semantic detector.

Positive values mark indefinite things, temporal/similarity prepositions,
and a few abstract word classes. Spatial and process vocabulary is negative.
Chat delimiters and a few text-formatting conventions have separate levels.
At a document boundary the estimate changes because no earlier text is present.
These rules approximate only a small part of this weak component's variation.
"""

READS = ()

# Values with earlier text, and at the document's first token.
CHAT_DELIMITERS = {
    '<|im_start|>': (-0.067, -0.137),
    '<|im_end|>': (0.014, -0.100),
    '<|endoftext|>': (-0.016, -0.050),
    '<tool_response>': (0.160, 0.026),
    '</tool_response>': (0.069, -0.079),
    '<think>': (0.133, -0.001),
    '</think>': (-0.073, -0.202),
    '<tool_call>': (-0.005, -0.155),
    '</tool_call>': (-0.050, -0.140),
}

# Each entry is a familiar word class, rather than a list of token ids.
WORD_CLASSES = (
    ('something anything nothing everything', 0.077),
    ('before after', 0.046),
    ('like unlike', 0.068),
    ('front back top bottom left right north south east west '
     'round surface space area region', -0.032),
    ('process processes processing develop develops developed developing '
     'development work works worked working operate operates operated '
     'operating operation operations produce produces produced producing '
     'production', -0.027),
    ('feel feels feeling feelings heart mind love hate fear happy sad', -0.029),
    ('power energy force forces pressure stress strength', -0.021),
    ('law legal illegal laws court justice attorney judge lawyer lawyers '
     'rights', 0.029),
    ('possible impossible possibly', 0.046),
    ('so thus hence therefore consequently', 0.023),
    ('limit limits limited limiting limitation limitations '
     'constant constants', 0.040),
    ('true false bool boolean', 0.021),
)
WORD_CLASSES = tuple((frozenset(words.split()), value)
                     for words, value in WORD_CLASSES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()

    if token in CHAT_DELIMITERS:
        value = CHAT_DELIMITERS[token][int(first)]
    elif '\xa0' in token and not text:
        value = 0.016
    elif token == '  ':
        value = -0.019
    elif text == '、':
        value = 0.024
    elif text == '---':
        value = -0.065
    elif text in ('":"', '","', '{"') and token.startswith(' '):
        value = -0.078
    elif text in ("'", '\\'):
        value = 0.012
    elif text == '\\n':
        value = -0.019
    else:
        value = -0.0013
        for words, level in WORD_CLASSES:
            if word in words:
                value = level
                break
        else:
            if any('\uac00' <= ch <= '\ud7af' for ch in text):
                value = -0.016
            elif text.isascii() and text.isalpha():
                if len(word) > 5 and word.endswith('ment'):
                    value = -0.015

    if first and token not in CHAT_DELIMITERS:
        if word in ('a', 'an'):
            value = 0.050 if text.istitle() else -0.084
        elif word == 'the':
            value = -0.049 if text.istitle() else -0.111
        elif word in ('this', 'that'):
            value = -0.060
        elif word in ('of', 'to', 'for', 'and', 'or', 'but', 'with', 'by'):
            value = -0.070
        elif text in (',', '.'):
            value = 0.035
        elif text == '#':
            value = -0.151
        elif text == '(':
            value = -0.117
        elif text.isdigit():
            value = 0.019
        else:
            value -= 0.009
    return doc, float(value)

"""Approximate the strong lexical responses of a discourse/qualification feature.

Theory, opinions, conclusions and discussion are strongest; analysis, explanations,
comments and exceptions are weaker. Capitalized forms of section-label words
get stronger predictions.
論/论 and related discussion words are strong multilingual triggers. We also
recognize split word pieces and a few immediate phrases, including negative
rest/remainder-of responses. State resets per document.
Unlisted tokens are zero: this is vocabulary recognition, not argument evaluation.
"""
import re

READS = ()

# Approximate response bands for related discourse vocabulary.
BANDS = (
    (1.33, {'theory', 'theories', 'theor', 'theoretical', 'theorists'}),
    (1.20, {'opinion', 'opinions', 'discussions', 'regardless'}),
    (1.00, {'discuss', 'discussed', 'discusses', 'discussing', 'discourse', 'whether'}),
    (0.85, {'conclusions', 'conclus'}),
    (0.70, {'unless', 'thesis', 'dissertation', 'essay', 'essays', 'commentary',
            'debate', 'debates', 'disc', 'talk'}),
    (0.53, {'analysis', 'explanation', 'explanations', 'determination',
            'conclude', 'concludes', 'concluded', 'concluding', 'analy'}),
    (0.42, {'analyses', 'analytical', 'analyzed', 'analysed', 'talks', 'talked',
            'forum', 'forums', 'agree', 'disagree', 'remarks', 'commented'}),
    (0.30, {'argue', 'argues', 'argued', 'agreed', 'agrees', 'belief', 'notion',
            'review', 'reviews', 'reviewed', 'comparison', 'evaluation', 'talking'}),
    (0.22, {'explain', 'explains', 'explained', 'explaining', 'argument',
            'judgment', 'thoughts', 'consideration', 'inference', 'whatever'}),
)
HEADINGS = {'conclusion': 1.95, 'discussion': 2.05, 'opinion': 1.55,
            'theory': 1.50, 'theories': 1.50, 'introduction': 0.66, 'whether': 1.26}
TRAILING_WORD = re.compile(r'[A-Za-z]+$')


def lexical_value(token):
    word = token.strip(' _-')
    lower = word.lower()
    if word[:1].isupper() and lower in HEADINGS:
        return HEADINGS[lower]
    if lower in {'comment', 'comments'}:
        if word.isupper():
            return 1.0
        return 0.72 if word[:1].isupper() else (0.5 if lower == 'comments' else 0.67)
    special = {'conclusion': 1.18, 'discussion': 1.5,
               'theoretically': 0.95, 'introduction': 0.26}
    if lower in special:
        return special[lower]
    for value, words in BANDS:
        if lower in words:
            return value
    if word in {'論', '论'}:
        return 5.1
    if word == '论坛':
        return 1.13
    if '論' in word or '论' in word:
        return 2.3
    if word in {'론', '논', 'luận'}:
        return 2.5
    if word in {'观点', '我认为', '不管是', '总之', '谈'}:
        return 1.1
    if word in {'认为', '認為', '不管', '談', 'мн'}:
        return 0.75
    if word in {'分析', '观念', '意见', '的意见', '評', '评', '議'}:
        return 0.57
    if word in {'と思います', '议', '问', 'вывод'}:
        return 0.44
    return 0.0


def piece_value(piece, word):
    """Recognize discourse morphemes split across tokens."""
    p, w = piece.lower(), word.lower()
    if w.startswith('conclu'):
        if p == 'clusion':
            return 1.95 if word.isupper() else 1.0
        if p == 'clusions':
            return 1.5 if word[:1].isupper() else 0.85
        if p in {'clus', 'ions'}:
            return 1.05
    if w.startswith('discuss') and p in {'ssion', 'ussion', 'ussions', 'uss', 'ussed'}:
        return 1.15 if word[:1].isupper() else 0.62
    if w.startswith('opinion') and p in {'inion', 'inions'}:
        return 1.4 if word[:1].isupper() else 1.12
    if w.startswith('theor') and p in {'oret', 'oretical', 'ories'}:
        return 1.1 if p == 'oretical' else 0.9
    if w == 'introduction' and p == 'roduction':
        return 0.65 if word.isupper() else 0.16
    return 0.54 if w == 'analysis' and p == 'ysis' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous, tail = ('', '') if reset else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = TRAILING_WORD.search((tail + token)[-64:])
    tail = match[0] if match else ''
    value = lexical_value(token)
    if not value and token.isascii() and token.isalpha():
        value = piece_value(token, tail)
    if not reset and set(token.strip()) == {'\ufffd'}:
        # A final UTF-8 fragment can finish a theory/discussion character.
        char = prefix.text_prefixes[-1][-1:]
        value = {'论': 6.4, '論': 4.2, '논': 3.6, '론': 2.5}.get(char, value)
    if word == 'of':
        if previous in {'theory', 'theories'}:
            value = 0.45
        elif previous in {'discussion', 'explanation'}:
            value = 0.25
        elif previous in {'opinion', 'opinions', 'conclusion', 'conclusions',
                          'regardless', 'talk'}:
            value = 0.18
        elif previous in {'rest', 'remainder'}:
            value = -0.50
    if word == 'on' and previous in {
        'comment', 'comments', 'commentary', 'opinion', 'discussion'
    }:
        value = 0.25
    if word == 'summary' and previous == 'in':
        value = 0.43
    return (doc, word, tail), value

programs.luna:
"""Approximate a sparse reasoning-and-discourse signal with word cues.

The strongest cues name theory, conclusions, opinions, conditions, or
discussion. Related analysis and text-structure terms get smaller predictions;
the rules also recognize a few Chinese and Russian equivalents.
"""

READS = ()

STRONG_CUES = (
    "whether", "unless", "regard", "theor", "conclus", "opinion",
    "discuss",
)

RELATED_CUES = (
    "analysis", "analys", "comment", "talk", "agree", "argu", "explan",
    "essay", "summary", "remark", "introduction", "thesis",
)

WEAK_CUES = ("forum", "determin", "question", "whatever", "review", "evaluat")
CHINESE_DISCUSSION = ("分析", "談", "谈", "认为", "意見", "意见")
CHINESE_DEBATE = ("讨论", "討論", "辩论", "辯論")
CHINESE_VIEWPOINT = ("观点", "觀點")
CHINESE_IDEAS = ("观念", "觀念", "坛", "壇")
RUSSIAN_REASONING = ("обществ", "вывод")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if any(word.startswith(cue) for cue in STRONG_CUES):
        return None, 1.1
    if word == "disc":
        return None, 0.6
    if word in ("论", "論"):
        return None, 5.0
    if "论" in word or "論" in word:
        return None, 1.4
    if any(cue in word for cue in CHINESE_DEBATE):
        return None, 1.6
    if any(cue in word for cue in CHINESE_VIEWPOINT):
        return None, 1.0
    if any(cue in word for cue in CHINESE_DISCUSSION):
        return None, 0.7
    if any(cue in word for cue in CHINESE_IDEAS):
        return None, 0.5
    if any(word.startswith(cue) for cue in RUSSIAN_REASONING):
        return None, 0.4
    if word.startswith("мн"):
        return None, 0.6
    if any(word.startswith(cue) for cue in RELATED_CUES):
        return None, 0.6
    if word.startswith(("clus", "ssion")):
        return None, 0.8
    if any(word.startswith(cue) for cue in WEAK_CUES):
        return None, 0.25
    return None, 0.0

programs.sol:
"""Approximate a lexical response to knowledge and certainty.

'I know/understand/remember' is strongly negative; 'to know' is positive,
especially after want or need. Negation usually weakens knowledge claims. 'I'm
sure' is strong but 'make sure' is weak. Related assurance and memory
words have smaller responses. Some following complements retain a small
response. Signs are activation values, not judgments about truth.
State resets at each document; other tokens predict zero.
"""
READS = ()
NEGATED = {'not', "'t", '’t', 'never', 'dont', 'cannot'}
SELF = {'am', "'m", '’m'}
SEEKING = {'want', 'wants', 'wanted', 'need', 'needs'}
# Default, first-person, infinitive, and negated responses.
VERBS = {
    'know': (-1.1, -3.4, 0.85, -0.4),
    'understand': (-1.2, -3.0, 0.1, -0.85),
    'remember': (-1.1, -2.4, -0.15, -0.85),
    'recall': (-0.5, -1.65, -0.24, -0.6),
    'see': (-0.05, -0.73, 0.22, -0.02),
    'believe': (-0.08, -0.62, 0.12, 0.0),
    'think': (0.04, -0.35, 0.12, 0.0),
    'hope': (-0.08, -0.62, 0.12, 0.0),
    'mean': (0.1, -1.05, 0.27, 0.15),
    'can': (0.0, -0.27, 0.0, 0.0),
}
RELATED = {
    'certainly': -1.5, 'surely': -1.05, 'capable': -0.72,
    'understood': -0.68, 'understands': -1.2, 'familiar': -0.54,
    'known': -0.39, 'seen': -0.3, 'saw': -0.32, 'aware': -0.45,
    'recognize': -0.4, 'recognise': -0.5, 'recognized': -0.36,
    'understanding': -0.21, 'indeed': -0.29, 'definitely': -0.34,
    'guess': -0.5, 'suspect': -0.6, 'suppose': -0.24,
    'agree': -0.3, 'yes': -0.3, 'yeah': -0.54, 'wondering': 0.36,
    '知道': -0.85, '我知道': -1.7, '你知道': -1.1, '都知道': -2.0,
    '熟': -1.2, '记得': -1.1, '記得': -0.9, '懂得': -0.7,
    '当然': -0.87, '的确': -1.5, '确实': -0.85, '理解': -0.35,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior, before, last = ('', '', 0.0)
    if carry is not None and carry[0] == doc:
        _, prior, before, last = carry
    token = prefix.token_strings[-1]
    raw = token.strip()
    word, prev, prev2 = raw.lower(), prior.lower(), before.lower()
    mode = 0
    if prev == 'to':
        mode = 2
    elif prev == 'i':
        mode = 1
    elif prev in NEGATED:
        mode = 3
    value = VERBS[word][mode] if word in VERBS else RELATED.get(word, 0.0)
    if word == 'know':
        if prev == 'to' and prev2 in SEEKING:
            value = 2.25
        elif prev in {'you', 'we', 'they', 'all', 'everyone'}:
            value = -2.2
            if prior[0].isupper():
                value = -3.4 if prev == 'you' else -2.6
            if prev2 in {'do', 'did', 'if', 'when', 'let'}:
                value = -1.3
        elif prev in {'me', 'us', 'should', 'can', 'may', 'might', 'not'}:
            value = -0.25
    elif word == 'understand' and prev == 'to' and prev2 in SEEKING:
        value = 0.75
    elif word == 'sure':
        value = -2.95 if prev in SELF else -1.4
        if prev in {'make', 'making', 'made', 'makes'}:
            value = 0.275 if prev2 == 'to' else -0.22
        elif prev in NEGATED:
            value = -1.15 if prev2 in SELF else -0.85
        elif prev in {'be', 'for'}:
            value = -0.72 if prev == 'be' else -0.35
    elif word in {'knew', 'knows'}:
        value = -2.4 if prev == 'i' else -1.5
    elif word == 'course':
        value = -0.3
        if prev == 'of':
            value = -1.13 if prior[0].isupper() else -0.9
    elif word == 'respect':
        value = 1.15 if prev == 'with' else 0.4
    elif word in {'knowledge', 'understanding'}:
        if prev == 'my':
            value = -0.72 if word == 'knowledge' else -1.1
        elif prev in {'our', 'their', 'your'}:
            value = -0.35
    # Capitalized verbs often introduce a heading or instruction.
    if raw and raw[0].isupper():
        if word in {'hope', 'think', 'believe', 'see', 'seen'}:
            value = 0.0
        elif word in {'know', 'remember', 'understand'}:
            value = -0.65 if word != 'understand' else -0.87
        elif word == 'sure':
            value = -1.7 if token.startswith(' ') else -1.27
        elif word == 'certainly' and not token.startswith(' '):
            value = -0.95
    if prev in {'know', 'knows', 'knew', 'understand', 'remember', 'see'}:
        if word in {'that', 'the', 'it', 'you', 'this', 'your', 'of'}:
            value += 0.16 * last
    if word == 'of' and prev in {'capable', 'aware', 'understanding'}:
        value = -0.35
    elif prev == 'respect' and word in {'to', 'of'}:
        value = 0.2 if word == 'to' else 0.6
    elif prev == 'known' and word == 'for':
        value = 0.25
    elif prev in {'familiar', 'familiarity'} and word == 'with':
        value = -0.4
    return (doc, raw, prior, value), float(value)

programs.haiku:
"""Knowledge and certainty words, such as "know", "sure", "understand", "of course",
"remember". The component is negative on these words, most strongly when they directly
follow a subject ("I know", "you know", "I'm sure"), and mildly positive after "to"
("want to know"). Everything else predicts 0."""

KNOW = {"know", "knew", "knows", "known", "knowing", "sure", "certainly", "remember",
        "understand", "understood", "realize", "recall", "recognize", "familiar", "aware",
        "course", "surely", "definitely", "guess", "suppose", "agree"}
SUBJ = {"i", "i'm", "i’m", "i'd", "i’ll", "i've", "i’ve", "we", "you", "he", "she", "they"}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in KNOW:
        return None, 0.0
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if prev == "to":
        return None, 0.5
    if prev in SUBJ:
        return None, -2.0
    return None, -0.7

programs.sol:
"""Approximate the component's prominent understanding/finding-out vocabulary.

Word-piece cues include understand, overview, exploration, and Chinese 了解.
Related vocabulary has weaker positive values; some plain knowing/reporting
words have small negative values. The signal continues onto connectors in
'understanding of', 'familiar with', 'insight into', and 'learn more about'.
Only three recent tokens are kept, resetting at each document boundary.

This is a partial lexical explanation, not general semantic inference.
Unmatched pieces return zero: many idiosyncratic token effects and longer
context effects are omitted. Constants are estimated from training examples.
"""
READS = ()

# Familiarity, comprehension, and introduction vocabulary in other languages.
# Translations are cues, not an assumption of equal response across languages.
TRANSLATIONS = {
    word: value
    for value, words in (
        (4.35, '了解'),
        (3.75, '不了解'),
        (4.00, '了解一下 深入了解'),
        (3.60, '详细了解'),
        (3.45, '了解到 瞭解'),
        (2.90, '了解更多'),
        (1.58, '据了解'),
        (1.75, '介绍 介紹 介绍一下 详细介绍'),
        (2.10, '介绍了'),
        (1.65, '熟悉'),
        (1.25, '掌握'),
        (0.95, '理解 懂'),
        (0.75, '认识 清楚 深入'),
        (0.67, '解 清 明白 探 探索 认识到'),
        (1.70, 'hiểu'),                    # Vietnamese: understand
        (1.30, '소개'),                    # Korean: introduction
        (1.10, '이해'),                    # Korean: understanding
        (1.50, '知って'),                  # Japanese: know
    )
    for word in words.split()
}
LEARNING = {'learn', 'learned', 'learning', 'learns'}
INFORMATION = set('information info detail details article articles book books '
                  'story stories question questions curious informed read'.split())
SPEAKING = set('talk talks talked talking think thinks thinking thought '
              'worry worried worrying worries'.split())


def lexical(word):
    if word in TRANSLATIONS:
        return TRANSLATIONS[word]
    if word.startswith('misunderstand') or word == 'misunderstood':
        return 0.72
    if word == 'understandable':
        return 0.53
    if word.startswith('understand') or word == 'understood':
        return 1.3 if word == 'understanding' else 1.04
    if 'familiar' in word or word == 'acquainted':
        return 0.75
    if word.startswith('comprehend') or word in {'comprehension', 'grasp'}:
        return 0.6
    if word.startswith(('aware', 'insight')):
        return 0.55
    if word == 'overview':
        return 1.15
    if word.startswith('explor') or word == 'delve':
        return 0.73
    if word.startswith('investigat'):
        return 0.5 if word.endswith(('tion', 'tions')) else 0.8
    if word.startswith('introduc'):
        return 0.5 if word == 'introduction' else 0.29
    if word in LEARNING:
        return 0.22 if word == 'learn' else 0.14
    if word in {'known', '-known'}:
        return 0.65 if word.startswith('-') else 0.12
    if word in {'know', 'knew', 'information', 'data', 'sure', 'tell', 'told'}:
        return -0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    word = prefix.token_strings[-1].strip().lower()
    prev = recent[-1] if recent else ''
    value = lexical(word)
    if word == 'about':
        value = 0.25
        if prev in LEARNING or (
            prev == 'more' and any(w in LEARNING for w in recent)
        ):
            value = 1.5
        elif prev in {'know', 'knows', 'knowledge', 'knowledgeable'}:
            value = 0.95
        elif prev in INFORMATION or prev == 'more':
            value = 0.7
        elif prev in SPEAKING:
            value = 0.08
        elif prev in {'ask', 'asked', 'asking', 'inquire'}:
            value = 0.47
    elif word == 'into':
        value = (1.1 if prev in {'insight', 'insights', 'delve', 'investigation'}
                 else 0.03)
    elif word == 'of':
        if prev in {'understanding', 'overview'}:
            value = 0.96
        elif prev in {'aware', 'awareness', 'grasp', 'knowledge'}:
            value = 0.5
    elif word == 'with' and prev in {
        'familiar', 'unfamiliar', 'familiarity', 'acquainted'
    }:
        value = 0.55
    elif word == 'to' and prev == 'introduction':
        value = 0.68
    elif word == 'more' and prev in LEARNING:
        value = 0.61
    elif word == 'known' and prev in {'well', 'widely', 'best', 'better'}:
        value = 0.48
    elif word in {'the', 'that', 'what', 'how', 'it'} and prev in {
        'understand', 'understanding'
    }:
        value = 0.27 if word == 'the' else 0.09
    elif word in {'understand', 'understanding'}:
        if prev in {'better', 'deep', 'deeper', 'keen', 'basic'}:
            value += 0.5
        elif prev in {'i', 'my', 'the'}:
            value -= 0.25
    return (doc, (recent + (word,))[-3:]), float(value)

programs.luna:
"""Mark words for understanding, knowledge, and investigation."""

READS = ()

ABOUT = {"about"}
UNDERSTANDING = {
    "understanding", "understand", "understood", "comprehend",
    "known", "overview", "认识到", "明白", "conoc",
}
INQUIRY = {
    "investigate", "investig", "explore", "explored",
    "查", "察", "探", "وضح", "解",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "about":
        value = 0.45
    elif word == "understanding":
        value = 1.00
    elif word == "understand":
        value = 0.65
    elif word == "understood":
        value = 0.60
    elif word in UNDERSTANDING:
        value = 0.45
    elif word in INQUIRY:
        value = 0.45
    else:
        value = 0.0
    return None, value

programs.sol:
"""A sparse lexical model of familiar expression endings.

Strong responses mark 'in terms of', 'make sense', 'make sure',
'in order', 'take place', and 'take into account'. Small positive
baselines remain on a few expression-ending nouns. Intervening words
weaken the 'in' cue; recognized expressions can continue onto 'of'.
There are also a few 'en' expressions and Go 'make' allocation forms.
This models the strong collocation responses, not the weak background.
History is short, case-insensitive, and reset between documents.
"""

READS = ()

MAKE = {'make', 'makes', 'making', 'made'}
TAKE = {'take', 'takes', 'taking', 'taken', 'took'}
KEEP = {'keep', 'keeps', 'keeping', 'kept'}

# Words completing expressions beginning with "in".
IN_ENDINGS = {
    'terms': 3.53, 'term': 1.35, 'order': 1.22, 'place': 1.43,
    'view': 1.20, 'line': 1.12, 'lines': 0.98, 'mind': 1.17,
    'sense': 1.15, 'response': 0.67, 'sight': 0.56,
    'context': 0.67, 'practice': 0.58, 'detail': 0.65,
    'question': 0.98, 'range': 0.62, 'words': 1.6, 'time': 0.38,
}
DEFAULTS = {
    'terms': 0.38, 'sense': 0.65, 'account': 0.23,
    'consideration': 0.10, 'respect': 0.25, 'sure': 0.12,
    'track': 0.23, 'mind': 0.13, 'view': 0.09, 'order': 0.07,
}


# How strongly a recognized expression continues onto the following 'of'.
OF_CONTINUATIONS = {
    'terms': 1.01, 'term': 1.45, 'view': 0.78, 'order': 0.65,
    'line': 0.66, 'place': 0.42, 'sense': 0.27, 'use': 0.56,
    'context': 0.65, 'light': 0.80, 'care': 0.54, 'track': 0.52,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = [] if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous = history[-1] if history else ''
    value = DEFAULTS.get(word, 0.0)

    if word in IN_ENDINGS:
        # Allow 'in general terms' or 'in this sense', with attenuation.
        for distance, old in enumerate(reversed(history[-3:])):
            if old == 'in':
                strength = IN_ENDINGS[word] * (0.50 ** distance)
                value = max(value, strength)
                break
    if word == 'of' and previous in OF_CONTINUATIONS:
        value = OF_CONTINUATIONS[previous] * carry[2]
    if previous in MAKE:
        value = {
            'sense': 2.90, 'sure': 1.40, 'clear': 1.0,
            'use': 1.19, 'note': 1.1,
        }.get(word, value)
    if word == 'sense' and any(w in MAKE for w in history[-3:]):
        value = max(value, 1.45)
    if previous in TAKE:
        value = {
            'place': 1.79, 'care': 0.98, 'charge': 0.57,
            'part': 0.78, 'account': 1.75,
        }.get(word, value)
    if previous in KEEP and word == 'track':
        value = 0.96
    if previous == 'into':
        value = {
            'account': 3.10, 'consideration': 2.46,
        }.get(word, value)
    if previous == 'with' and word == 'respect':
        value = 0.79
    if previous == 'of' and word == 'course':
        value = 0.73
    if previous == 'other' and word == 'words':
        value = 1.08
    if previous == 'like' and word == 'terms':
        value = 1.17
    if previous == 'en':
        value = {'place': 1.07, 'question': 0.94,
                 'cuenta': 0.94, 'compte': 1.05}.get(word, value)
    if previous == 'in' and word in {'-place', '-line'}:
        value = 1.70 if word == '-place' else 0.95
    # Go's built-in make: slice, map, and channel allocation.
    if previous in MAKE and word.startswith(('([]', '(map', '(chan')):
        value = 0.94 if word.startswith('([]') else 0.55
    if word.isalpha():
        history = (history + [word])[-5:]
    elif raw.strip():
        history = []
    return (doc, history, value), float(value)

"""A partial detector of body parts and physical orientation.

Hands and sides have the largest lexical responses. A fading count of body,
movement, and mechanical words strengthens concrete readings. Articles and
common idioms refine this; unspaced/capitalized tokens are weaker. State
resets per document. Tool delimiters have a negative offset. Small unrelated
word-specific background activations are omitted. Several CJK body/side
characters and hyphenated hand/side forms get fixed strengths.
"""
READS = ()
BODY = set(
    'hand palm finger thumb arm head face eye ear nose mouth neck shoulder '
    'body torso chest spine wrist elbow hip leg foot knee heel toe'.split()
)
DIRECTIONS = set(
    'left right front back forward backward upward downward upper lower '
    'top bottom rear middle inside outside side opposite horizontal vertical '
    'clockwise upright'.split()
)
MOVEMENT = set(
    'hold held holding place placed placing bend bent push pushed pushing '
    'pull pulled pulling turn turned turning lift lifted lifting stretch '
    'stretched move moving touch touching fold folded point pointing'.split()
)
PHYSICAL_TERMS = set(
    'arrow surface shaft spindle lever wheel roller cylinder curved rotation '
    'artery vein muscle bone'.split()
)
POSTURE = set('stand standing sit sitting relaxed calm gesture facing'.split())
CONTEXT = BODY | DIRECTIONS | MOVEMENT | PHYSICAL_TERMS | POSTURE
STRENGTH = {
    'hand': .45, 'palm': .48, 'finger': .35, 'thumb': .35,
    'arm': .21, 'head': .21, 'face': .21, 'neck': .21,
    'front': .53, 'left': .32, 'right': .25, 'back': .18,
    'forward': .12, 'backward': .18, 'rear': .18,
    'upward': .29, 'downward': .29, 'clockwise': .39, 'upright': .39,
}
SUBJECT_OR_AUXILIARY = set(
    'i he she we they who has had have was were is be been are'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, context = ('', 0.0) if carry is None or carry[0] != doc else (
        carry[1], .9 * carry[2]
    )
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    # Regular plurals and directional adverbs share their singular stems.
    root = {'feet': 'foot', 'bodies': 'body', 'arteries': 'artery'}.get(word, word)
    if root.endswith('s') and root[:-1] in CONTEXT:
        root = root[:-1]
    body = root in BODY
    if root in CONTEXT:
        value = STRENGTH.get(root, .13 if root in POSTURE else .00)
        value += .17 * context
        if previous == 'the' or (body and previous in {'a', 'an'}):
            value += .13
        if not raw.startswith(' '):
            value -= .10
        if raw.lstrip()[:1].isupper():
            value -= .05
        if body and previous in {'left', 'right'}:
            value += .20
        if root in {'left', 'right'} and previous in SUBJECT_OR_AUXILIARY:
            value -= .20
        if root == 'hand' and previous in {'other', 'another', 'by', 'at'}:
            value -= .20
        if root == 'back' and previous in {'go', 'get', 'come', 'came', 'going'}:
            value -= .20
        if root == 'forward' and previous in {'look', 'looking', 'put'}:
            value -= .25
    elif root == 'of' and previous in {'front', 'hand', 'palm'}:
        value = .19
    elif word in {'手', '左', '右', '头', '頭', '掌'}:
        value = .26
    elif word in {'-hand', '-handed', '-left', '-right'}:
        value = .88 if word == '-hand' else .63
    elif word == '<tool_call>':
        value = -.19
    elif word in {'</tool_call>', '<tool_response>'}:
        value = -.09
    else:
        value = -.002
    mention = root in CONTEXT and raw.startswith(' ')
    return (doc, root, context + float(mention)), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:5938, a body-and-side-words detector.

What it does: it fires on words for the hands and arms (hand, hands, palm, thumb,
finger, wrist, arm, right-hand/left-hand compounds), on the head and face, and on
spatial direction words (left, right, front, back, upper, bottom, upright, facing,
clockwise, mirror). The direction words count when they are spatial: after an article,
determiner, preposition or conjunction ("the left", "in front", "and right"). After a
pronoun or auxiliary they are verbs ("who left", "was right") and stay quiet; after a
LaTeX backslash ("\\left(") they are silent. Posture words (stand, sitting, seated,
kneel) fire weakly. Words of this kind that follow other body words within a few tokens
(a physical "close the right nostril" setting) fire about 40% harder. Chat/tool tags
(<tool_call>) dip slightly negative. Everything else predicts 0.

Main idea: the component reads the lexical concept "body part or body-side position",
not any particular context. Predictions are per token, from the token's own text and
the one or two tokens before it.
"""
READS = ()

# Hands and arms: strongest. Right/left compounds ("left hand") boost the hand word.
HANDS = {"palm": 0.8, "palms": 0.8, "thumb": 0.8, "thumbs": 0.8, "-hand": 0.9, "-handed": 0.7,
         "hand": 0.45, "hands": 0.55, "finger": 0.5, "fingers": 0.55, "wrist": 0.3,
         "arm": 0.35, "arms": 0.2, "手": 0.3, "手指": 0.2}
# Head and face
HEAD = {"head": 0.29, "face": 0.22, "shoulders": 0.4, "neck": 0.22, "cheeks": 0.4,
        "eye": 0.14, "eyes": 0.08, "头": 0.2, "頭": 0.16}
# Spatial direction words
SIDES = {"left": 0.6, "right": 0.5, "-right": 0.6, "-left": 0.5, "front": 0.65, "back": 0.25,
         "upper": 0.25, "rear": 0.3, "upward": 0.35, "downward": 0.3, "upright": 0.45,
         "clockwise": 0.55, "facing": 0.3, "mirror": 0.35, "sideways": 0.4, "frontal": 0.55,
         "bottom": 0.15, "左": 0.4, "右": 0.45}
# Body posture
POSTURE = {"stand": 0.28, "standing": 0.2, "sitting": 0.27, "seated": 0.3, "sit": 0.1,
           "kneel": 0.3, "bow": 0.2}
# Words that make a direction word spatial (article, determiner, preposition, conjunction)
SPATIAL_BEFORE = {"the", "a", "an", "in", "to", "and", "his", "her", "my", "your", "their",
                  "our", "of", "on", "at", "from", "or", "both", "one", "other", "its"}
# Body words that make the surrounding text a physical-body context
BODY = set(HANDS) | set(HEAD) | {"leg", "legs", "knee", "knees", "foot", "feet", "nostril",
                                  "nose", "elbow", "ear", "ears", "mouth", "body", "chest"}
TOOL_TAGS = {"<tool_call>", "<tool_response>", "</tool_call>"}


def _word(s):
    """The token's text: case kept for the exact-form entries, lowercased otherwise."""
    w = s.strip()
    return w if w in SIDES or w in HANDS or w in HEAD or w in POSTURE else w.lower()


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    word = _word(strs[-1])
    prev = strs[-2].strip().lower() if len(strs) > 1 else ""
    if word in TOOL_TAGS:
        return None, -0.15
    if word in SIDES:
        if prev == "\\":  # LaTeX \left( \right)
            return None, 0.0
        w = SIDES[word] if prev in SPATIAL_BEFORE else 0.3 * SIDES[word]
    elif word in HANDS:
        w = 0.9 if prev in ("left", "right", "-left", "-right") else HANDS[word]
    elif word in POSTURE:
        w = POSTURE[word]
    else:
        return None, HEAD.get(word, 0.0)
    if word in SIDES or word in HANDS or word in HEAD:
        recent = [s.strip().lower() for s in strs[-9:-1]]
        if any(x in BODY for x in recent):
            w *= 1.4
    return None, w

"""Layer-0 MLP neuron 5939 (a down_proj component): it switches on, negatively, on
verbs of showing, conveying and representing, when they say what something means or
displays: "X indicates / reflects / highlights / illustrates / conveys / signifies /
represents / depicts / suggests ...", on "point out" (the "out" in it), and on their
Chinese counterparts 体现, 象征, 突出, 表达, 展现, 反映, 强调, 表现, 呈现, 代表.
Other tokens get 0. The program predicts that activation: about -1.2 for the strongest
verbs, -0.6 for medium ones, -0.25 for nouns and weaker forms, 0 elsewhere."""

READS = ()

STRONG = ("reflect", "highlight", "indicate", "illustrate", "convey", "signify", "embody",
          "emphasize", "communicate", "reinforce", "underscore", "showcase")
MEDIUM = ("represent", "depict", "denote", "demonstrate", "portray", "capture", "suggest",
          "symbolize", "imply")
WEAK = ("symbol", "mirror", "signal", "emphasis", "reflection", "illustration", "indicator",
        "showing", "communication", "show", "reveal", "express", "exhibit", "display")
CHINESE_STRONG = ("体现", "象征", "突出", "表达", "展现", "反映", "强调", "表现", "呈现")
CHINESE_MEDIUM = ("代表", "表明", "说明", "传递")


def forms(word):
    stem = word[:-1] if word.endswith("e") else word
    if word.endswith("y"):
        return {word, word[:-1] + "ies", word[:-1] + "ied", word + "ing"}
    return {word, stem + "s", stem + "es", stem + "ed", stem + "ing", stem + "e"}


LEXICON = {}
for words, value in ((STRONG, -1.2), (MEDIUM, -0.6), (WEAK, -0.25)):
    for word in words:
        for form in forms(word):
            LEXICON[form] = value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token == "out" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower().startswith("point"):
            return carry, -1.2
    if token in LEXICON:
        return carry, LEXICON[token]
    if any(c in token for c in CHINESE_STRONG):
        return carry, -1.2
    if any(c in token for c in CHINESE_MEDIUM):
        return carry, -0.6
    return carry, 0.0

programs.sol:
"""Approximate a negative response to ol-like spelling fragments.

Short Latin ol- syllables, Cyrillic оль/оля, and a doubled l split over two
pieces are the main rules. An ol-ending piece also affects the next piece
of the word. Capitalization and document starts adjust the strength.
Other tokens receive a near-zero prediction; diffuse lexical activity is
not modeled. Only the previous token is carried, within the same document.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    s = token.lower()
    word = s.strip()
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    p = previous.lower()
    value = 0.0

    if word == 'ol':
        value = -0.19
        if s.startswith(' '):
            value -= 0.25
        if token.strip() == 'Ol':
            value -= 0.19
    elif s.startswith('ol'):
        if len(s) == 3:
            ending = s[-1]
            if ending in 'aiu':
                value = -0.44
            elif ending in 'fs':
                value = -0.38
            elif ending == 'o':
                value = -0.24
            else:
                value = -0.10
        else:
            value = -0.12 if len(s) == 4 else -0.03
    elif word == 'pol':
        value = -0.18 if token.strip().islower() else -0.34
    elif word == 'col':
        value = 0.06
    elif 'ol' in s:
        value = -0.01
    elif s == 'оль':
        value = -0.66
    elif s == 'оля':
        value = -0.50
    elif s == 'олов':
        value = -0.19
    elif word == 'l':
        value = -0.055 if token.strip() == 'L' else -0.015

    continuation = bool(s) and s[0].isalpha()
    if p.endswith('ol') and continuation:
        value -= 0.20 if len(p.strip()) <= 4 else 0.05
        if s.startswith('l'):
            value -= 0.13
    if p.endswith('l') and s.startswith('l'):
        value -= 0.15
        if p.strip() == 'l' and s == 'l':
            value -= 0.16
    if p.endswith('l') and s.startswith('ol'):
        value -= 0.65
    if p.endswith('b') and s.startswith('ol'):
        value += 0.12
    if p == ' ol':
        value -= 0.13
        if previous == ' Ol':
            value -= 0.15
    if p == 'оль':
        value -= 0.13
    if p.endswith('л') and s.startswith('л'):
        value -= 0.30
    if p.endswith('ل') and s.startswith('ل'):
        value -= 0.10

    if first:
        if word == 'ol':
            value = -1.60
        elif s == 'оль':
            value = -1.65
        elif word == 'l':
            value = -0.54 if token.strip() == 'L' else -0.30
    return (doc, token), float(value)

programs.haiku:
"""Publication-name detector (a negative-going component).

It goes negative on the words that name a periodical, proceedings or conference in a
reference or title, as in "... Proceedings of FOCS", "... IEEE International Conference on ...",
"Journal of ...", and on the capital "J" that starts an abbreviated journal name ("J. Phys.").
Strongest on the name word itself ("Proceedings", "Journal", "IEEE", "Conference"), and
strongest of all on the linking "of"/"on" right after one of those. Other tokens are 0."""

READS = ()

NAME_CUES = {"Journal", "journal", "JOURNAL", "Proceedings", "proceedings", "Proc", "IEEE",
             "Conference", "conference", "[J"}
TITLE_WORDS = {"Society", "Science", "Sciences", "Review", "Reviews", "Rev", "Phys", "Physics",
               "Mathematics", "Mathematical", "Math", "Annals", "Ann", "Advances", "Adv", "Acad",
               "Encyclopedia", "Magazine", "Letters", "Transactions", "Trans", "Reports", "Trends",
               "Issue", "Vol", "Symposium", "International"}
LINKERS = {"of", "on", "in", "for", "the", "and"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if word in NAME_CUES:
        return None, -1.4
    if word in LINKERS and prev in NAME_CUES:
        return None, -2.4
    if word == "J":
        return None, -0.6
    if word in TITLE_WORDS:
        return None, -0.4
    if prev in NAME_CUES:
        return None, -0.15
    return None, 0.0

programs.sol:
"""Respond to offices, leadership titles, and professional responsibility.

A small role lexicon gives leadership titles the largest scores, staff and
institutions smaller scores. Compound ranks strengthen the response; 'of'
continues it into the organization name. A few occupational word endings and
Chinese/Japanese office words handle titles split into pieces. Other tokens
predict zero. This is lexical matching, not a claim to understand the text.
"""
READS = ()

CORE = {
    'secretary': 4.5, 'president': 3.8, 'director': 3.6,
    'chairman': 3.9, 'chancellor': 4.5, 'general': 0.7,
    'mayor': 2.0, 'senator': 2.2, 'manager': 2.0, 'head': 0.6,
}
RANKS = frozenset('''
chief governor commissioner deputy superintendent minister treasurer
archbishop ambassador lieutenant colonel admiral ceo vice
'''.split())
PROFESSIONAL = frozenset('''
editor assistant administrator officer captain commander clerk principal
representative spokesman spokeswoman spokesperson executive professor
manager chair dean officials adviser advisor inspector supervisor pastor trustee
coordinator curator librarian architect judge attorney sheriff
'''.split())
STAFF = frozenset('''
coach staff lecturer instructor scientist researcher journalist designer
lawyer doctor surgeon consultant engineer expert member leader agent
associate priest nurse analyst faculty senior dr prof mr sir lord justice
'''.split())
INSTITUTIONS = frozenset('''
board council senate department administration agency committee commission
ministry bureau headquarters cabinet office branch management affairs administrative
'''.split())

PLURAL_ROLES = frozenset(CORE) | RANKS | PROFESSIONAL | STAFF | INSTITUTIONS

def words_at_score(groups):
    return {w: score for score, words in groups for w in words.split()}

OFFICES = words_at_score((
    (7.0, '主任 副主任 委书记 副书记 副总经理 部部长'),
    (5.5, '董事长 董事長 会长 會長 秘书长 秘書長 院长 院長 总经理 '
          '總經理 局长 市长 部长 总监 副主席 副会长 处处长 局局长 党委书记 纪委书记'),
    (4.0, '主席 委员 委員 理事 总裁 首席 常委'),
    (2.5, '书记 校长 校長 主管 经理 大使 首相 总理 副 厅 廳 委'),
    (1.5, '负责人 代表 官员 官員 委员会 委員會 部 事 務 司 教授 '
          '办公室 研究院 总统 主播 장 대통령'),
    (0.6, '官 会 會 社 处 所 員 员 書 主 师 師 总 總 任 局 院'),
))
ENDINGS = words_at_score((
    (4.0, 'ancellor irector'),
    (2.0, 'puty utenant ariat'),
    (1.0, 'ologist ographer minist essor'),
    (0.2, 'or ate ist'),
    (0.5, 'ician ator eur aries ister ident presidency directorate'),
))


def lexical(token):
    text = token.strip().lstrip('_/-.')
    word = text.lower()
    if text in OFFICES:
        return OFFICES[text]
    root = word[:-1] if word.endswith('s') else word
    if root not in PLURAL_ROLES:
        root = word
    score = CORE.get(root, 0.0)
    if root in RANKS:
        score = 3.0
    elif root in PROFESSIONAL:
        score = 1.6
    elif root in STAFF:
        score = 0.6
    elif root in INSTITUTIONS:
        score = 0.8
    score = CORE.get(root, score)
    if text[:1].isupper() and root in {'director', 'minister', 'chief', 'officer', 'mayor'}:
        score += 0.8
    if text[:1].isupper() and root == 'general':
        score = 1.3
    if root in {'board', 'office', 'management', 'affairs'}:
        score = 0.4 if not text[:1].isupper() else 1.0
    if text == 'Affairs':
        score = 2.0
    if root == 'dean':
        score = 1.9 if text[:1].isupper() else 2.8
    if root != word:
        score *= 0.8
    if not token[:1].isspace():
        score = ENDINGS.get(word, score)
        if word in {'assistant', 'manager', 'professor', 'director', 'vice', 'dr'}:
            score *= 0.65
        if token.startswith(('_', '.')):
            score *= 0.5
    return score


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous, old = (0.0, '') if reset else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-')
    value = lexical(token)
    if word == 'of':
        value = previous
        if old in {'director', 'president', 'secretary'}:
            value = min(5.8, 0.7 * previous + 1.4)
        elif old == 'general':
            value = 0.5 * previous + 0.4
        elif old in {'head', 'board', 'ministry', 'office', 'bureau'}:
            value = 1.8
    elif word in {'for', 'at'}:
        value = 0.4 * previous
        if word == 'for' and old in {'center', 'centre', 'institute', 'society'}:
            value = 1.0
        elif word == 'for' and old == 'responsible':
            value = 0.7
    elif not token[:1].isspace() and word in {'ial', 'ship', 's'}:
        value = 0.6 * previous
    if word == 'president' and old in {'vice', 'vice-'}:
        value = 6.2
    elif word == 'director' and old in {'executive', 'managing', 'assistant', 'deputy'}:
        value = 7.0
    elif word == 'general' and old in {'attorney', 'inspector', 'secretary', 'director'}:
        value = 5.5
    elif word == 'minister' and old in {'chief', 'prime', 'foreign'}:
        value = 5.5
    elif word == 'secretary' and old in {'assistant', 'deputy', 'under', 'foreign'}:
        value = 7.0
    if token in {'长', '長'}:
        value = 4.5 if old and old[-1] in '部局厅处院校会社所店司队台师外' else 0.8
    if reset and value >= 2.5:
        value += 1.5
    saved = 0.0 if word in {'of', 'for', 'at'} else value
    return (doc, saved, word), float(value)

programs.luna:
"""Recognize words for people, official titles, and public bodies.

Many high-activation examples are a named office or occupation. A smaller
signal marks institutional nouns. Reassembling a word across subword tokens
also lets the rule work when a word is split into pieces.
"""

READS = ()

OFFICES = {
    "president", "secretary", "director", "minister", "lord",
    "ceo", "chief", "governor", "judge",
}
OCCUPATIONS = {
    "assistant", "administrator", "administrators", "editor",
    "professor", "teacher", "officer", "official", "scientist",
    "scientists", "designer", "designers", "spokesperson",
    "researcher", "researchers", "counselor", "engineer", "manager",
}
INSTITUTIONS = {
    "department", "board", "council", "company", "corporation",
    "committee", "agency",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, previous = "", ""
    else:
        _, word, previous = carry

    token = prefix.token_strings[-1]
    last_word = ""
    saw_letter = False
    for char in token:
        if char.isalpha():
            word += char
            last_word = word
            saw_letter = True
        else:
            if word:
                previous = word.casefold()
            word = ""

    value = 0.0
    if saw_letter:
        key = last_word.casefold()
        if key in OFFICES:
            value = 3.0
        elif key in OCCUPATIONS:
            value = 0.65
        elif key in INSTITUTIONS:
            value = 0.45
        elif key == "of" and previous == "ceo":
            value = 2.0

    return (doc, word, previous), value

"""A lexical heuristic for people/peer words and relational alternatives."""
READS = ()

CLOSE_ASSOCIATES = {
    "friend", "friends", "colleague", "colleagues",
    "teammate", "teammates", "amigo",
}
PEOPLE = {
    "beneficiary", "guest", "guests", "wife", "husband", "hubby",
    "student", "students", "person", "people", "someone", "somebody",
    "member", "members", "fellow", "daughter", "son", "parent",
    "parents", "partner", "partners", "他人",
}
RELATIONAL_WORDS = {
    "other", "another", "alternative", "alternatively", "different",
    "similarly", "similar", "related", "equivalent", "corresponding",
    "next", "duplicate", "pairs", "pair", "closest", "mating",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower().strip()
    if word in CLOSE_ASSOCIATES:
        return None, 4.0
    if word in PEOPLE:
        return None, 1.25
    if word in RELATIONAL_WORDS:
        return None, 0.65
    return None, 0.0

programs.sol:
"""Approximate a multilingual grammatical-form and spelling response.

The largest positives are Persian prepositions. Smaller signed responses
cover Persian endings/initial letters and short grammatical forms in other
languages. Recent words and script-specific letters resolve homographs.
Most tokens receive zero; this is not a semantic or syntactic parser.
"""
READS = ()

# Persian prepositions: in, with, to, on, without, colloquial object marker.
PERSIAN_PREPOSITIONS = {
    ' در': 7.3, ' با': 4.5, ' به': 3.7, ' بر': 3.5,
    ' بدون': 2.2, ' رو': 2.7,
}
PERSIAN_FORMS = {
    # Common vowel, plural, person, participle and copula spellings.
    'ا': 1.0, 'ه': 1.05, 'ای': 1.0, 'ها': 2.2,
    'ده': 2.4, 'ند': 1.6, 'ته': 1.55, 'ست': 1.1,
    'ام': 0.9, 'اش': 1.3, 'د': 1.3, 'ی': -0.25,
    'ان': -1.1, ' است': 1.9, 'ود': 1.7, 'ز': 1.7,
    # Preposition spellings without a leading space; 'ra' marks objects.
    'در': 4.8, 'با': 2.9, 'به': 3.7, 'بر': 2.6,
    'از': 3.0, 'را': 1.7,
    # Contrasting word-initial letters and the pronoun 'man' (I).
    ' ک': -1.75, ' س': -1.1, ' ج': -1.1, ' ل': -1.55,
    ' ب': -0.95, ' ت': -0.6, ' ف': -0.95,
    ' من': -1.5, 'من': -1.5, ' ان': -1.9,
    ' ر': 1.0, ' ه': 0.7, ' ا': 0.4,
}
DUTCH_FORMS = {
    'de': 1.55, 'te': 1.2, 'met': 1.2, 'op': 1.1,
    'bij': 0.4, 'door': 0.8, 'u': 0.65, 'uw': 0.5,
    'dat': -0.65, 'dit': -0.85, 'om': -0.65, 'dan': -0.8,
    'ons': -1.3, 'aan': -0.45, 'in': 0.2, 'en': -0.2,
    'tot': 0.75, 'deze': 0.85, 'wel': 0.55, 'zou': 0.85,
    'dus': 0.9, 'doen': 0.8, 'alle': 1.1, 'niet': 0.3, 'uit': 0.3,
}
ROMANIAN_FORMS = {
    'pe': 4.0, 'cu': 3.1, 'la': 2.8, 'din': 1.7, 'de': 1.9,
    'în': 1.25, 'pentru': 1.5, 'este': 1.7, 'nu': 1.6,
    'sau': 1.8, 'despre': 2.5, 'să': 0.65, 'fi': 0.75,
    'au': 0.8, 'care': 0.7, 'prin': 1.5, 'ace': -2.3, 'ei': -1.7,
}
# Small language-identification lexicons, not activation lookup tables.
WORDS = {
    'Dutch': frozenset('''het een van zijn voor niet deze wordt heeft
        hebben ook maar bij naar geen zich wij onze kunnen worden
        zal zullen waar wanneer daar jij zij hun jullie jouw mijn'''.split()),
    'Romanian': frozenset('''și şi în pentru sunt sau că acest
        această acestui acesta acestea aceea acelea acolo atunci deci
        unei unui fost poate dintre către despre fiind suntem
        trebuie deoarece'''.split()),
    'Nordic': frozenset('''og och det ikke inte till til att för är
        vår jeg hva hvordan hvor har som med skal'''.split()),
    'Polish': frozenset('''jest nie sie się przez dla jak czy oraz
        jego tego ich ale żeby gdzie kiedy który jestem'''.split()),
}
CHARACTERS = {
    'Persian': 'یگپچک', 'Romanian': 'ășțşţ', 'Nordic': 'åø',
    'Polish': 'ąćęłńśźż', 'Ukrainian': 'іїєґ',
}
DECAY = {
    'Persian': 0.96, 'Dutch': 0.99, 'Romanian': 0.99,
    'Nordic': 0.99, 'Polish': 0.98, 'Ukrainian': 0.96,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending = '', ''
        scores = dict.fromkeys(DECAY, 0.0)
    else:
        _, previous, pending, old_scores = carry
        scores = {name: value * DECAY[name]
                  for name, value in old_scores.items()}
    token = prefix.token_strings[-1]
    word = token.strip().lower()

    # Complete words across token splits, retaining only a short partial word.
    for char in token.lower():
        if char.isalpha():
            pending = (pending + char)[-32:]
        else:
            for language, markers in WORDS.items():
                scores[language] += pending in markers
            pending = ''
    for language, letters in CHARACTERS.items():
        spelling = token.lower() if language == 'Nordic' else token
        scores[language] += sum(char in letters for char in spelling)
    now = scores.copy()
    for language in ('Dutch', 'Romanian', 'Nordic'):
        now[language] += pending in WORDS[language]

    # Weak responses to preposition spellings even outside their language.
    value = {' pe': 0.55, ' op': 0.2, ' met': 0.15,
             ' w': 0.2}.get(token, 0.0)
    if token in PERSIAN_PREPOSITIONS:
        value = PERSIAN_PREPOSITIONS[token]
    elif token == 'ز' and previous == ' ا':  # az, 'from'
        value = 5.3
    elif scores['Persian'] > 0.5:
        value = PERSIAN_FORMS.get(token, value)
        if token == 'ا' and previous == ' ر':  # ra, object marker
            value = 2.6
        elif token == 'ای' and previous == ' بر':  # baraye, 'for'
            value = 2.55
        elif len(word) == 1 and word in 'کگپچ' and token != ' ک':
            value = -1.5 if word == 'چ' else -0.65

    initial = token[:1].isspace()
    language = max(('Dutch', 'Romanian', 'Nordic'), key=now.get)
    if now[language] <= 1.5:
        language = None
    if word in ('în', 'pentru', 'despre'):
        language = 'Romanian'
    if language == 'Dutch':
        if initial and word in DUTCH_FORMS:
            value = DUTCH_FORMS[word]
        elif token.lower() in ('de', 'te'):
            value = 1.15 if token.lower() == 'de' else 0.5
    elif language == 'Romanian':
        if initial and word in ROMANIAN_FORMS:
            value = ROMANIAN_FORMS[word]
            if token.strip()[0].isupper():
                value *= 0.55
        elif token in ('ul', 'ui', 'ului'):  # definite/genitive endings
            value = {'ul': 0.65, 'ui': 1.1, 'ului': 0.85}[token]
        elif token in ('ș', 'ț', 'ş', 'ţ'):
            value = -0.65
    elif language == 'Nordic' and token.lower() == ' de':
        value = 0.7
    if scores['Polish'] > 0.5 and initial:
        value = {'w': 0.65, 'dla': 0.5, 'przez': 0.7}.get(word, value)
    if scores['Ukrainian'] > 0.5:
        value = {'з': 1.65, 'у': 1.65, 'до': 0.9,
                 'ц': -1.25}.get(word, value)
        if token == ' к':
            value = -1.4
    return (doc, token, pending, scores), float(value)

programs.luna:
"""Predict large responses to Persian word-starts: در, از, and است."""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous_raw = prefix.token_strings[-2]
        previous = previous_raw.strip()
    else:
        previous_raw = ""
        previous = ""

    at_word_start = not raw or raw[0].isspace() or prefix.position == 0
    if at_word_start and token == "در":
        value = 7.5
    elif token == "از" or (
        token == "ز" and previous == "ا" and previous_raw[:1].isspace()
    ):
        value = 5.8
    elif at_word_start and token == "است":
        value = 1.9
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A token-spelling approximation to a flower-related negative signal.

花 is strongest; compounds and English flower/rose forms are weaker. These
rules also fire in names and non-botanical uses. Split flower spellings get
a negative response on their final piece. Smaller rules cover flame/gas
vocabulary and chat delimiters. Unlisted tokens get zero: this deliberately
omits the many small, unrelated token-specific responses seen in training.
The message-start marker is stronger at the beginning of a document.
"""
READS = ()

CHAT_BOUNDARIES = {
    '<|im_start|>': 0.14,
    '</tool_response>': -0.32,
    '<tool_call>': -0.14,
    '</tool_call>': -0.10,
    '<think>': -0.10,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = CHAT_BOUNDARIES.get(token, 0.0)
    at_start = (prefix.position == 0 or
                prefix.document_ids[-1] != prefix.document_ids[-2])
    if token == '<|im_start|>' and at_start:
        value = 0.225
    if word == '花':  # Flower; also the Chinese spelling for 'spend'.
