programs.haiku:
"""Flower and blossom words, the things this component is about.

Layer 0's MLP output component 5947 is a token detector. It goes strongly
negative on the token that names a flower (flower, rose, the Chinese 花 and
its compounds) and more weakly on words for bright bloom-like things (flame,
fireworks, bouquet, petal, blossom, jasmine). Everywhere else it is near 0.
This program writes a fixed negative value for each such token and 0 for all
other tokens, using only the token's text.
"""

READS = ()

# Each concept is a set of word forms (lower case, no leading space) and a value.
FLOWER_WORDS = {"flower", "flowers", "flowering", "floral"}
ROSE_WORDS = {"rose", "roses", "rosemary"}
FLAME_WORDS = {"flame", "flames", "fireworks", "firework", "bouquet"}
PETAL_WORDS = {"petal", "petals", "blossom", "blossoms", "jasmine"}
WEAK_WORDS = {"gas", "spark", "sparks", "fire", "cherry"}

# Chat-template markup: a small, steady offset on these tokens.
MARKUP_VALUES = {
    "</tool_response>": -0.3,
    "<tool_call>": -0.14,
    "</tool_call>": -0.1,
    "<|im_start|>": 0.15,
}

# Chinese: 花 by itself is the flower (and "spend", as in 花钱); its compounds
# and other flower names (玫瑰 rose, 樱 cherry, 梅 plum, 菊 chrysanthemum, 兰 orchid,
# 莲 lotus, 瓣 petal) fire too.
FLOWER_CHARS = "花瓣玫樱梅菊兰莲焰"


def value(token):
    word = token.strip().lower()
    if token.strip() == "花":
        return -3.0
    if any(ch in FLOWER_CHARS for ch in token):
        return -1.3
    if word in FLOWER_WORDS:
        return -1.8
    if word in ROSE_WORDS or word in FLAME_WORDS:
        return -1.1
    if word in PETAL_WORDS:
        return -0.7
    if word in WEAK_WORDS:
        return -0.3
    return MARKUP_VALUES.get(token.strip(), 0.0)


def step(carry, prefix, upstream):
    return None, value(prefix.token_strings[-1])

