BLOOM_WORDS = ("floral", "blossom", "bloom", "petal")
ROSE_WORDS = ("rose", "sakura", "chrysanthemum", "willow")
FIRE_WORDS = ("flame", "firework", "ember", "arson")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()
