programs.sol:
"""A lexical passage/means/origin detector, strongest on 'through'.

Smaller cues include related prepositions, translations, and words resembling
through. Literal traversal before 'through' lowers the response; acquisition
verbs raise it. A following determiner or whitespace retains a small echo.
The program remembers only the previous token, resetting between documents.
"""

READS = ()

CUES = {
    'through': 7.15, 'thru': 4.9, 'via': 2.92, 'throughout': 2.5,
    'from': 0.74, 'into': 0.73, 'during': 0.94, 'using': 0.6,
    'by': 0.08, 'across': 0.51, 'beyond': 0.89, 'past': 0.31,
    'durch': 2.0, 'через': 2.5, 'través': 4.3, 'através': 3.9,
    'attravers': 3.2, '通过': 2.4, '通過': 1.8, '透過': 2.2,
    '透过': 1.7, '从': 0.53, '從': 0.45,
    'though': 1.55, 'although': 0.83, 'thorough': 1.74,
    'thoroughly': 0.69, 'rough': 0.9, 'trough': 1.74,
    'breakthrough': 1.27, 'throughput': 2.55,
    'stream': 0.67, 'streams': 0.39, 'streaming': 0.5,
    'downstream': 0.96, 'mainstream': 0.83,
}

TRAVERSAL = set('''
    go goes going gone went walk walks walking walked
    run runs running ran travel travels traveling travelling traveled travelled
    flow flows flowing passed path paths line lines journey journeys
'''.split())
PASS = {'pass', 'passes', 'passing'}
ACQUISITION = set('''
    get gets getting got come comes came coming
    obtain obtains obtained obtaining achieve achieves achieved achieving
    receive receives received receiving generate generates generated generating
    provide provides provided providing
'''.split())


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('_./-(["\'')
    lower = word.lower()
    value = CUES.get(lower, 0.0)

    if lower == 'through':
        if word.istitle():
            value = 8.35
        elif not raw.startswith((' ', '-')):
            value = 6.08
        if previous in TRAVERSAL:
            value -= 1.5
        elif previous in PASS:
            value -= 2.6
        elif previous in ACQUISITION:
            value += 1.3
    elif lower == 'from':
        if word.isupper():
            value = 0.65
        elif word.istitle():
            value = 1.0
        elif raw.startswith('\t'):
            value = 0.45
        elif raw.startswith('_'):
            value = 1.05
    elif lower == 'via' and raw != ' via':
        value = 1.5
    elif lower == 'though' and previous in {'even', 'as'}:
        value = 0.8
    elif lower not in CUES and '通过' in word:
        value = 2.4 if word.startswith('通过') else 1.8

    if previous == 'through':
        if lower == 'the':
            value += 1.0
        elif lower == 'a':
            value += 0.77
        elif lower in {'an', 'this', 'that', 'his', 'her', 'its', 'your'}:
            value += 0.45
        elif raw.isspace():
            value += 0.19

    return (document, lower), float(value)

