"""A local detector for mathematical typesetting syntax.

TeX font and accent names give negative responses, strongest for compound names.
The immediately following brace, variable, or sized delimiter also responds.
Matrix environments, square roots, and Mathematica boxes have local rules too.
This does not interpret the mathematics. State is a short text suffix and the
last control word; it resets at document boundaries. Ordinary text is near zero.
"""
import re

READS = ()
FONTS = {
    'mathbb': -2.9, 'mathcal': -2.5, 'mathfrak': -3.8,
    'mathsf': -3.1, 'mathscr': -3.0, 'mathbf': -1.2,
    'mathit': -1.6, 'mathrm': -0.6, 'Bbb': -1.8,
    'textbf': -2.8, 'texttt': -2.5, 'textit': -2.2,
    'textsc': -1.9, 'textrm': -1.8, 'textnormal': -1.5,
    'textup': -1.5, 'boldsymbol': -2.5,
}
CONTROLS = {
    'widetilde': -3.8, 'widehat': -3.1, 'overline': -2.9,
    'underline': -1.6, 'tilde': -1.6, 'hat': -0.6, 'vec': -0.3,
    'operatorname': -4.0, 'nolimits': -3.2, 'limits': -1.5,
    'mathop': -2.0, 'mbox': -1.8, 'displaystyle': -1.1,
    'textstyle': -2.1, 'scriptstyle': -3.0, 'scriptscriptstyle': -3.6,
    'qquad': -1.7, 'quad': -0.5, 'infty': -1.1,
    'ldots': -1.2, 'cdots': -1.9, 'dagger': -1.4,
    'varphi': -1.2, 'varepsilon': -2.1, 'otimes': -1.4,
    'hfill': -1.5, 'hspace': -0.7, 'textwidth': -1.4,
    'kappa': -0.9, 'zeta': -1.0, 'nabla': -0.9, 'cdot': -0.4,
    'wedge': -1.2, 'setminus': -1.0, 'varnothing': -1.6,
    'footnote': -1.4, 'overset': -0.9, 'underset': -0.9,
    'rfloor': -1.5, 'lfloor': -1.1, 'rbrace': -1.5, 'lbrace': -1.3,
    'dfrac': -1.5, 'frac': 0.1, 'sqrt': 0.1, 'text': -0.2,
    'Vert': -1.2, 'vert': -1.2, 'langle': -0.9, 'rangle': -1.8,
    'left': 0.1, 'right': -0.1, 'big': -0.6, 'Big': -0.7,
    'bigl': -1.7, 'bigr': -2.1, 'bigg': -1.1,
    'biggl': -2.3, 'biggr': -2.0,
    'begin': 0.24, 'end': 0.0, 'label': 0.24, 'ref': 0.16,
}
COMMON = set(('alpha beta gamma delta eta theta lambda mu pi rho sigma '
              'tau phi Delta partial nabla int sum sin cos tan log ln lim '
              'in le ge leq geq sim approx equiv times cdot wedge '
              'rm bf cal overset underset').split())
META = {'begin', 'end', 'label', 'ref'}
SIZERS = {'left', 'right', 'big', 'Big', 'bigl', 'bigr', 'bigg', 'biggl', 'biggr'}
COMMAND = re.compile(r'\\([A-Za-z]+)$')
BARE_STYLE = re.compile(r'\b((?:math|wide|over|under|bold|operator)[A-Za-z]+)$')
MATRIX = re.compile(r'\\(begin|end)\{([pbBvV]|small)matrix(\}?)$')
ROOT = re.compile(r'(sqrt|√)(\(?)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous, age = '', '', 9
    else:
        _, history, previous, age = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    before = history
    history = (history + token)[-80:]
    match = COMMAND.search(history) or BARE_STYLE.search(history)
    value = 0.003
    if match:
        name = match[1]
        value = FONTS.get(name, CONTROLS.get(name, 0.003))
        previous = name if name in FONTS or name in CONTROLS or name in COMMON else ''
        age = 0
    else:
        age += 1
        if previous in META:
            if age == 1:
                value = {'begin': 0.06, 'end': -0.18}.get(previous, 0.0)
        elif previous and age == 1:
            spaced = token.startswith(' ')
            if previous in SIZERS:
                if len(s) == 1:
                    value = -1.5 if previous == 'left' else -1.3
                    value -= 0.8 if s == '|' else 0.2 if s in '[]<>' else 0
                    value -= 0.7 if spaced else 0
                else:
                    value = -0.8 if s.endswith('\\') else -0.5
            elif s.startswith('{'):
                value = -0.8 if s == '{' else -0.6
                value -= 0.8 if spaced else 0
            elif s and s.isascii() and s.isalpha():
                value = -0.8
                if previous in FONTS:
                    value = -1.4
                    if previous in ('mathbb', 'Bbb') and s in {'R', 'C', 'Z', 'N'}:
                        value = -2.7
            elif s.isdecimal() and previous in ('frac', 'dfrac'):
                value = -2.5
            elif token.isspace() and previous in ('mathbf', 'mathrm', 'frac', 'sqrt'):
                value = -1.9
            elif s in ('_', '^') and spaced:
                value = -1.6
            else:
                value = -0.4
        elif previous and age == 2:
            if len(s) == 1 and s.isalpha() and previous in ('mathbb', 'Bbb'):
                value = -0.8
            elif s.isalnum() and previous in ('frac', 'dfrac', 'sqrt'):
                value = -0.5
            elif s.isalpha() and previous in FONTS:
                value = -0.25
    matrix = MATRIX.search(history)
    if matrix:
        ending = matrix[1] == 'end'
        if matrix[3]:
            value = -1.1 if ending else -0.5
        else:
            value = -3.0 if matrix[2] == 'p' else -2.4
            if matrix[2] == 'small':
                value = -1.1
            value -= 0.7 if ending else 0
    root = ROOT.search(before)
    if root and s.isdecimal():
        value = -1.15 if root[1] == 'sqrt' else -0.43
        if root[2]:
            value *= 0.24
    if history.endswith(('SuperscriptBox', 'UnderoverscriptBox')):
        value = -1.2
    elif history.endswith('FractionBox'):
        value = -0.45
    elif history.endswith('RowBox'):
        value = -0.2
    elif 'Box' in before[-60:] and token in ('[List', '["'):
        value = -0.45
    return (doc, history, previous, age), float(value)

