import re

READS = ()

# LaTeX math-mode commands (backslash names) and how strongly they drive this unit.
FONT_CMDS = {"mathbb", "mathcal", "mathbf", "mathit", "mathrm", "mathfrak", "mathsf", "mathtt"}
OVER_CMDS = {"over"}
ARG_CMDS = {"frac", "sqrt", "left", "right", "big", "Big", "bigg", "Bigg", "overline", "hat", "widehat",
            "partial", "mathbb", "mathcal", "mathbf", "mathit", "mathrm", "mbox", "text", "operatorname",
            "displaystyle", "scriptstyle", "scriptscript", "overline", "vec", "cdot", "quad", "wide", "tilde"}
CMD_END = re.compile(r"\\([A-Za-z]{2,})$")
WORD = re.compile(r"[A-Za-z]+$")


def step(carry, prefix, upstream):
    """Negative on LaTeX math-mode commands: the letters that spell a command such as \\mathbb or \\over,
    and the token right after a command such as \\left( or \\frac{."""
    before = "".join(prefix.token_strings[-6:-1])
    cur = prefix.token_strings[-1]
    m = CMD_END.search(before)
    if m is None:
        return carry, 0.0
    cmd = m.group(1)
    if WORD.fullmatch(cur):
        if cmd in FONT_CMDS or cmd in OVER_CMDS:
            return carry, -2.5
        return carry, -0.5
    if cmd in ARG_CMDS:
        return carry, -1.0
    return carry, 0.0
